def normalize_automotive_stt_text(text: str) -> str:
    if not text:
        return ""
    t = text.strip()

    replacements = [
        (r"\bباشیم\b", "با شیم"),
        (r"\bبا\s*سیم\b", "با شیم"),
        (r"\bباسیم\b", "با شیم"),
        (r"\bبا\s*شین\b", "با شیم"),
        (r"\bباشین\b", "با شیم"),
        (r"\bسیم\s*دار\b", "با شیم"),
        (r"\bسیم‌دار\b", "با شیم"),
        (r"\bشیم\s*دار\b", "با شیم"),
        (r"\bشیم‌دار\b", "با شیم"),
        (r"\bبدون\s*سیم\b", "بدون شیم"),
        (r"\bبدون\s*شین\b", "بدون شیم"),
        (r"\bبی\s*سیم\b", "بدون شیم"),
        (r"\bبی‌سیم\b", "بدون شیم"),
        (r"\bبی\s*شیم\b", "بدون شیم"),
        (r"\bبی‌شیم\b", "بدون شیم"),
        (r"\bلنتا\b", "لنت ها"),
        (r"\bلنتای\b", "لنت های"),
        (r"\bپرایدی\b", "پراید"),
        (r"\bتیبایی\b", "تیبا"),
        (r"\bپژویی\b", "پژو"),
        (r"\bسمندی\b", "سمند"),
        (r"\bنیسانی\b", "نیسان"),
        (r"\bپیکانی\b", "پیکان"),
        (r"\bمزدایی\b", "مزدا"),
        (r"\bام\s*وی\s*ام\b", "MVM"),
        (r"\bایکس\s*۳۳\b", "X33"),
        (r"\bایکس\s*33\b", "X33"),
        (r"\bایکس\s*۲۲\b", "X22"),
        (r"\bایکس\s*22\b", "X22"),
        (r"\bایکس\s*۵۵\b", "X55"),
        (r"\bایکس\s*55\b", "X55"),
        (r"\bاس\s*۵\b", "S5"),
        (r"\bاس\s*5\b", "S5"),
        (r"\bاس\s*۳\b", "S3"),
        (r"\bاس\s*3\b", "S3"),
        (r"\bجی\s*۵\b", "J5"),
        (r"\bجی\s*5\b", "J5"),
        (r"\bجی\s*۴\b", "J4"),
        (r"\bجی\s*4\b", "J4"),
        (r"\bتی\s*۸\b", "T8"),
        (r"\bتی\s*8\b", "T8"),
        (r"\bشش\s*میل\b", "۶ میل"),
        (r"\bشیش\s*میل\b", "۶ میل"),
        (r"\bپنج\s*میل\b", "۵ میل"),
    ]
    for pattern, repl in replacements:
        t = re.sub(pattern, repl, t)

    t = re.sub(r"\s+", " ", t).strip()
    return t


GENERIC_CUSTOMER_PLACEHOLDERS = {
    "", "مشتری گرامی", "مشتری", "جناب آقای مشتری گرامی", "سرکار خانم مشتری گرامی",
    "جناب آقای مشتری", "سرکار خانم مشتری", "جناب آقای", "سرکار خانم", "آقای", "خانم",
    "نامشخص", "بدون نام", "null", "none", "...", "ندارد", "-", "—"
}


def is_missing_customer_name(customer_title: str) -> bool:
    t = (customer_title or "").strip()
    if t.lower() in GENERIC_CUSTOMER_PLACEHOLDERS:
        return True
    for p in ["جناب آقای", "سرکار خانم"]:
        if t.startswith(p) and t[len(p):].strip().lower() in GENERIC_CUSTOMER_PLACEHOLDERS:
            return True
    return False


def format_person_with_honorific(name_str: str, gender: str = "") -> str:
    t = (name_str or "").strip()
    if not t or t.lower() in GENERIC_CUSTOMER_PLACEHOLDERS:
        return "مشتری گرامی"

    is_female = str(gender).lower().strip() in ("female", "woman", "f", "زن", "خانم")
    words = re.split(r"[\s\-–—_،,]+", t)
    if any(w in FEMALE_INDICATORS for w in words):
        is_female = True

    if is_female:
        if t.startswith("سرکار خانم"):
            return t
        for prefix in ["جناب خانم", "سرکار خانم", "خانم", "بانو", "سرکار"]:
            if t.startswith(prefix):
                rest = t[len(prefix):].strip()
                return f"سرکار خانم {rest}"
        return f"سرکار خانم {t}"
    else:
        if (
            t.startswith("جناب آقای")
            or t.startswith("جناب سرهنگ")
            or t.startswith("جناب دکتر")
            or t.startswith("جناب مهندس")
        ):
            return t
        for prefix in ["جناب آقای", "جناب اقای", "آقای", "اقای", "جناب"]:
            if t.startswith(prefix):
                rest = t[len(prefix):].strip()
                if rest.startswith("آقای") or rest.startswith("اقای"):
                    rest = rest[4:].strip()
                if rest.startswith("سرهنگ") or rest.startswith("دکتر") or rest.startswith("مهندس"):
                    return f"جناب {rest}"
                return f"جناب آقای {rest}"
        return f"جناب آقای {t}"


def build_final_customer_title(parsed: dict, source_text: str = "") -> str:
    gender = parsed.get("customer_gender", "")
    raw_name = (parsed.get("customer_name") or parsed.get("customer_title") or "").strip()
    shop_name = (parsed.get("shop_name") or "").strip()

    for sep in [" – ", " - ", " — ", "–", "-"]:
        if sep in raw_name:
            parts = [p.strip() for p in raw_name.split(sep, 1)]
            raw_name = parts[0]
            if not shop_name and len(parts) > 1:
                shop_name = parts[1]
            break

    person_formatted = format_person_with_honorific(raw_name, gender)

    if shop_name in ("null", "None", "ندارد", "-", "—", "...", "فروشگاه", "لوازم یدکی"):
        shop_name = ""

    if source_text and shop_name:
        shop_keywords = ["لوازم یدکی", "یدکی", "فروشگاه", "بازرگانی", "پخش", "تعمیرگاه", "کلینیک", "مغازه"]
        if not any(kw in source_text for kw in shop_keywords):
            shop_name = ""

    if shop_name:
        return f"{person_formatted} – {shop_name}"
    return person_formatted


def get_telegram_user_formatted_name(user) -> str:
    if not user:
        return ""
    first = (getattr(user, "first_name", "") or "").strip()
    last = (getattr(user, "last_name", "") or "").strip()
    full = f"{first} {last}".strip()
    if not full:
        return ""
    return format_person_with_honorific(full)


def parse_typed_customer_name(raw_input: str) -> str:
    txt = (raw_input or "").strip()
    if not txt or txt.lower() in GENERIC_CUSTOMER_PLACEHOLDERS:
        return "مشتری گرامی"
    shop_part = ""
    person_part = txt
    for sep in [" – ", " - ", " — ", "،", "-"]:
        if sep in txt:
            parts = [p.strip() for p in txt.split(sep, 1)]
            person_part = parts[0]
            if len(parts) > 1:
                shop_part = parts[1]
            break
    if not shop_part and "لوازم یدکی" in person_part and not person_part.startswith("لوازم یدکی"):
        idx_s = person_part.find("لوازم یدکی")
        shop_part = person_part[idx_s:].strip()
        person_part = person_part[:idx_s].strip()

    formatted_person = format_person_with_honorific(person_part)
    if shop_part:
        return f"{formatted_person} – {shop_part}"
    return formatted_person


