def generate_pdf_bytes(order_data: dict) -> bytes:
    html_str = render_invoice_html(
        doc_type=order_data["doc_type"],
        customer_title=order_data["customer_title"],
        date_str=order_data["date"],
        items=order_data["items"],
        invoice_no=order_data.get("invoice_no", "........................."),
        attachment="دارد",
        order_data=order_data,
    )

    try:
        import weasyprint
        return weasyprint.HTML(string=html_str).write_pdf()
    except ImportError:
        pass

    with tempfile.TemporaryDirectory() as tmpdir:
        html_path = os.path.join(tmpdir, "invoice.html")
        pdf_path = os.path.join(tmpdir, "invoice.pdf")
        with open(html_path, "w", encoding="utf-8") as f:
            f.write(html_str)

        for browser in ["chromium", "chromium-browser", "google-chrome", "msedge"]:
            bin_path = shutil.which(browser)
            if bin_path:
                subprocess.run(
                    [
                        bin_path,
                        "--headless",
                        "--disable-gpu",
                        "--no-sandbox",
                        f"--print-to-pdf={pdf_path}",
                        "--no-pdf-header-footer",
                        html_path,
                    ],
                    check=True,
                )
                with open(pdf_path, "rb") as pf:
                    return pf.read()

    raise RuntimeError("برای ساخت PDF لطفاً weasyprint یا مرورگر Chromium نصب باشد.")


