def build_customer_full_title(person_name: str, shop_name: str = "") -> str:
    """ساخت عنوان استاندارد مشتری از روی نام شخص و نام مغازه/لوازم یدکی"""
    p_clean = (person_name or "").strip()
    s_clean = (shop_name or "").strip()
    if not p_clean and s_clean:
        return s_clean
    p_formatted = format_person_with_honorific(p_clean)
    if s_clean and s_clean not in ("-", "—", "ندارد", "null", "None"):
        if not any(s_clean.startswith(w) for w in ["لوازم یدکی", "فروشگاه", "بازرگانی", "پخش", "تعمیرگاه", "مغازه"]):
            s_clean = f"لوازم یدکی {s_clean}"
        return f"{p_formatted} – {s_clean}"
    return p_formatted


def register_customer_profile(person_name: str, shop_name: str = "", save_now: bool = True) -> dict:
    """ثبت یا بروزرسانی مشتری در دفترچه مشتریان بدون ایجاد تکراری"""
    global CUSTOMER_COUNTER
    full_title = build_customer_full_title(person_name, shop_name)
    if is_missing_customer_name(full_title):
        return None

    # بررسی عدم تکرار
    for cid, c_rec in REGISTERED_CUSTOMERS.items():
        if c_rec.get("full_title", "").strip() == full_title.strip():
            return c_rec

    CUSTOMER_COUNTER += 1
    cid = str(CUSTOMER_COUNTER)
    p_formatted = format_person_with_honorific(person_name) if person_name else full_title
    rec = {
        "id": cid,
        "person_name": p_formatted,
        "shop_name": (shop_name or "").strip(),
        "full_title": full_title,
        "created_at": get_today_jalali(),
    }
    REGISTERED_CUSTOMERS[cid] = rec
    if save_now:
        save_accounting_db()
    return rec


def parse_and_register_customer_text(raw_text: str, save_now: bool = True) -> dict:
    """
    تحلیل متن واردشده برای ثبت مشتری جدید (مثلاً «رضایی - لوازم یدکی بهار» یا «محمدی، فروشگاه پارس» یا فقط «حسینی»)
    و ثبت در لیست مشتریان.
    """
    txt = (raw_text or "").strip()
    person_part = txt
    shop_part = ""
    for sep in [" – ", " - ", " — ", "\n", "،", ",", "-", "–"]:
        if sep in txt:
            parts = [p.strip() for p in txt.split(sep, 1)]
            person_part = parts[0]
            if len(parts) > 1:
                shop_part = parts[1]
            break
    if not shop_part and "لوازم یدکی" in person_part and not person_part.startswith("لوازم یدکی"):
        idx_s = person_part.find("لوازم یدکی")
        shop_part = person_part[idx_s:].strip()
        person_part = person_part[:idx_s].strip()
    elif not shop_part and "مغازه" in person_part and not person_part.startswith("مغازه"):
        idx_s = person_part.find("مغازه")
        shop_part = person_part[idx_s + len("مغازه"):].strip()
        person_part = person_part[:idx_s].strip()

    return register_customer_profile(person_part, shop_part, save_now=save_now)


def sync_customers_from_existing_orders():
    """استخراج خودکار نام مشتریان از سفارش‌های قبلی موجود در دیتابیس تا هیچ مشتری قبلی از قلم نیفتد"""
    for rec in ACCOUNTING_ORDERS.values():
        od = rec.get("order_data") or {}
        c_title = (od.get("customer_title") or "").strip()
        if c_title and not is_missing_customer_name(c_title) and not c_title.startswith("تسویه کارخانه"):
            parse_and_register_customer_text(c_title, save_now=False)


def load_accounting_db(custom_path: str = None, merge: bool = False):
    """
    بارگذاری دیتابیس حسابداری و مشتریان از فایل JSON روی دیسک با حفظ کامل تمام سفارش‌ها و پرداخت‌های قبلی.
    اگر merge=True باشد (مثلاً هنگام بازیابی فایل بکاپ)، اطلاعات جدید با اطلاعات فعلی ادغام می‌شوند تا هیچ چیزی نپرد.
    """
    global ORDER_COUNTER, SETTLEMENT_BATCH_COUNTER, CUSTOMER_COUNTER
    target_path = custom_path or ACCOUNTING_DB_PATH
    if not os.path.exists(target_path):
        return
    try:
        with open(target_path, "r", encoding="utf-8") as f:
            data = json.load(f)

        if not merge:
            ACCOUNTING_ORDERS.clear()
            REGISTERED_CUSTOMERS.clear()

        # ۱. بارگذاری مشتریان ثبت‌شده
        customers_map = data.get("customers") or {}
        if isinstance(customers_map, dict):
            for cid, c_rec in customers_map.items():
                REGISTERED_CUSTOMERS[str(cid)] = c_rec
                try:
                    c_num = int(str(cid))
                    if c_num > CUSTOMER_COUNTER:
                        CUSTOMER_COUNTER = c_num
                except Exception:
                    pass

        # ۲. بارگذاری تمامی سفارش‌ها و پرداخت‌ها (حفظ ۱۰۰٪ اطلاعات قبلی)
        orders_map = data.get("orders") or {}
        for oid, rec in orders_map.items():
            oid_str = str(oid)
            od = rec.get("order_data") or {}
            for it in od.get("items", []):
                get_item_factory_prices(it)
            # اگر سفارش قبلاً پرداخت شده یا تسویه شده ولی actual_paid_amount در نسخه قبلی نداشته، مبلغ فاکتور را برایش حفظ می‌کنیم
            if rec.get("acc_status") in ("paid_unsettled", "settled_archived") and rec.get("actual_paid_amount") is None:
                fin = calculate_order_financials(od.get("items", []), order_data=od)
                rec["actual_paid_amount"] = fin["total_payable"]
                od["actual_paid_amount"] = fin["total_payable"]

            ACCOUNTING_ORDERS[oid_str] = rec
            ACTIVE_PAYMENT_ORDERS[oid_str] = rec
            try:
                num_id = int(oid_str)
                if num_id > ORDER_COUNTER:
                    ORDER_COUNTER = num_id
            except Exception:
                pass

        saved_order_cnt = data.get("order_counter", 1000)
        if isinstance(saved_order_cnt, int) and saved_order_cnt > ORDER_COUNTER:
            ORDER_COUNTER = saved_order_cnt

        saved_batch = data.get("settlement_batch_counter", 5000)
        if isinstance(saved_batch, int) and saved_batch > SETTLEMENT_BATCH_COUNTER:
            SETTLEMENT_BATCH_COUNTER = saved_batch

        saved_cust_cnt = data.get("customer_counter", 100)
        if isinstance(saved_cust_cnt, int) and saved_cust_cnt > CUSTOMER_COUNTER:
            CUSTOMER_COUNTER = saved_cust_cnt

        sync_customers_from_existing_orders()
        save_accounting_db()
        logger.info(f"✅ دیتابیس حسابداری بارگذاری شد ({len(ACCOUNTING_ORDERS)} سفارش، {len(REGISTERED_CUSTOMERS)} مشتری).")
    except Exception as e:
        logger.warning(f"Could not load accounting DB: {e}")


def save_accounting_db():
    """ذخیره آنی وضعیت سفارش‌های باز، تسویه‌نشده، بایگانی، پرداخت‌ها و لیست مشتریان در فایل JSON"""
    try:
        payload = {
            "order_counter": ORDER_COUNTER,
            "settlement_batch_counter": SETTLEMENT_BATCH_COUNTER,
            "customer_counter": CUSTOMER_COUNTER,
            "customers": REGISTERED_CUSTOMERS,
            "orders": ACCOUNTING_ORDERS,
        }
        with open(ACCOUNTING_DB_PATH, "w", encoding="utf-8") as f:
            json.dump(payload, f, ensure_ascii=False, indent=2)
    except Exception as e:
        logger.warning(f"Could not save accounting DB: {e}")


def register_or_update_accounting_order(
    oid: str,
    order_data: dict,
    customer_chat_id: int,
    default_acc_status: str = "open",
    customer_user_tag: str = "",
    customer_full_name: str = "",
) -> dict:
    """
    ثبت یا بروزرسانی سفارش در سیستم حسابداری مدیر:
    - هر پیش‌فاکتور جدید به صورت خودکار وارد «سفارش‌های باز» (acc_status = 'open') می‌شود.
    - اگر نام مشتری معتبر باشد، خودکار در دفترچه مشتریان نیز ثبت می‌شود.
    """
    oid = str(oid)
    order_data["order_id"] = oid
    for it in order_data.get("items", []):
        get_item_factory_prices(it)

    c_title = (order_data.get("customer_title") or "").strip()
    if c_title and not is_missing_customer_name(c_title) and not c_title.startswith("تسویه کارخانه"):
        parse_and_register_customer_text(c_title, save_now=False)

    existing = ACCOUNTING_ORDERS.get(oid)
    if existing:
        existing["order_data"] = order_data
        if order_data.get("actual_paid_amount") is not None:
            existing["actual_paid_amount"] = int(order_data["actual_paid_amount"])
        if customer_chat_id:
            existing["customer_chat_id"] = customer_chat_id
        if customer_user_tag:
            existing["customer_user_tag"] = customer_user_tag
        if customer_full_name:
            existing["customer_full_name"] = customer_full_name
        rec = existing
    else:
        rec = {
            "order_id": oid,
            "order_data": order_data,
            "customer_chat_id": customer_chat_id,
            "customer_user_tag": customer_user_tag,
            "customer_full_name": customer_full_name,
            "status": "proforma_issued",
            "acc_status": default_acc_status,  # "open" | "paid_unsettled" | "settled_archived"
            "actual_paid_amount": order_data.get("actual_paid_amount"),
            "created_at": order_data.get("date") or get_today_jalali(),
            "paid_at": "",
            "settled_at": "",
            "settlement_batch_id": "",
        }
        ACCOUNTING_ORDERS[oid] = rec

    ACTIVE_PAYMENT_ORDERS[oid] = rec
    save_accounting_db()
    return rec


def get_orders_by_acc_status(acc_status: str) -> list:
    res = [
        rec for rec in ACCOUNTING_ORDERS.values()
        if rec.get("acc_status", "open") == acc_status and rec.get("order_data", {}).get("items")
    ]
    res.sort(key=lambda r: int(str(r.get("order_id", "0"))) if str(r.get("order_id", "0")).isdigit() else 0, reverse=True)
    return res


def extract_jalali_year_month(date_str: str) -> str:
    s = to_en_str(str(date_str or "")).strip()
    m = re.match(r"^(\d{4})[/\-](\d{1,2})", s)
    if m:
        yr = int(m.group(1))
        mo = max(1, min(12, int(m.group(2))))
        return f"{yr:04d}/{mo:02d}"
    today = to_en_str(get_today_jalali())
    return today[:7]


def format_jalali_month_title(ym_str: str) -> str:
    if ym_str == "all":
        return "کل دوره‌ها (همه ماه‌ها)"
    try:
        parts = to_en_str(ym_str).split("/")
        yr = int(parts[0])
        mo = int(parts[1])
        m_name = JALALI_MONTH_NAMES.get(mo, "")
        return f"{m_name} {to_fa_num(yr)} ({to_fa_num(f'{yr:04d}/{mo:02d}')})"
    except Exception:
        return to_fa_num(ym_str)


def shift_jalali_year_month(ym_str: str, delta_months: int) -> str:
    try:
        parts = to_en_str(ym_str).split("/")
        yr = int(parts[0])
        mo = int(parts[1])
        total_m = (yr * 12 + (mo - 1)) + delta_months
        new_yr = total_m // 12
        new_mo = (total_m % 12) + 1
        return f"{new_yr:04d}/{new_mo:02d}"
    except Exception:
        return to_en_str(get_today_jalali())[:7]


def compute_customer_sales_and_profit_stats(month_key: str = "all") -> list:
    """
    محاسبه دقیق میزان فروش، مبلغ واقعی پرداختی، تراز حساب (بدهکار/بستانکار) و سود خالص برای هر مشتری
    فقط بر اساس سفارش‌های پرداخت‌شده (paid_unsettled و settled_archived).
    پیش‌فاکتورهای پرداخت‌نشده (open) در درآمد و سود مشتری محاسبه نمی‌شوند!
    """
    stats_by_cust = {}  # customer_title -> dict

    # ابتدا مشتریان ثبت‌شده را در دیکشنری آماده می‌کنیم
    for cid, c_rec in REGISTERED_CUSTOMERS.items():
        title = c_rec.get("full_title", "").strip()
        if title:
            stats_by_cust[title] = {
                "customer_id": cid,
                "customer_title": title,
                "paid_orders_count": 0,
                "open_orders_count": 0,
                "total_sets": 0,
                "invoiced_total": 0,
                "actual_paid_total": 0,
                "payment_diff_total": 0,
                "factory_payable_total": 0,
                "net_profit": 0,
                "order_ids": [],
            }

    for rec in ACCOUNTING_ORDERS.values():
        od = rec.get("order_data") or {}
        if not od.get("items"):
            continue
        ym = extract_jalali_year_month(od.get("date") or rec.get("created_at"))
        if month_key not in ("all", None, "") and ym != month_key:
            continue

        c_title = (od.get("customer_title") or "مشتری گرامی").strip()
        if c_title not in stats_by_cust:
            stats_by_cust[c_title] = {
                "customer_id": None,
                "customer_title": c_title,
                "paid_orders_count": 0,
                "open_orders_count": 0,
                "total_sets": 0,
                "invoiced_total": 0,
                "actual_paid_total": 0,
                "payment_diff_total": 0,
                "factory_payable_total": 0,
                "net_profit": 0,
                "order_ids": [],
            }

        st = rec.get("acc_status", "open")
        if st == "open":
            # پیش‌فاکتور پرداخت‌نشده جزو درآمد و سود حساب نمی‌شود
            stats_by_cust[c_title]["open_orders_count"] += 1
            continue

        fin = calculate_order_financials(od["items"], order_data=od, ord_rec=rec)
        entry = stats_by_cust[c_title]
        entry["paid_orders_count"] += 1
        entry["total_sets"] += fin["total_qty"]
        entry["invoiced_total"] += fin["total_payable"]
        entry["actual_paid_total"] += fin["actual_paid_amount"]
        entry["payment_diff_total"] += fin["payment_diff"]
        entry["factory_payable_total"] += fin["factory_payable_total"]
        entry["net_profit"] += fin["net_profit"]
        entry["order_ids"].append(str(rec.get("order_id", "")))

    result = list(stats_by_cust.values())
    result.sort(key=lambda x: (x["actual_paid_total"], x["paid_orders_count"], x["open_orders_count"]), reverse=True)
    return result


def generate_factory_settlement_pdf_bytes(selected_records: list, batch_id: str) -> tuple:
    """
    ساخت فاکتور تجمیعی تسویه با کارخانه (با اعمال ۲۰٪ تخفیف روی لیست قیمت کارخانه)
    برای سفارش‌های انتخاب‌شده توسط مدیر.
    """
    aggregated_map = {}
    order_ids = []
    customer_names = []
    total_customer_revenue = 0
    total_factory_list = 0
    total_factory_payable = 0

    for rec in selected_records:
        oid = str(rec.get("order_id", ""))
        order_ids.append(f"#{to_fa_num(oid)}")
        od = rec.get("order_data", {})
        c_title = od.get("customer_title", "مشتری")
        if c_title not in customer_names:
            customer_names.append(c_title)

        fin = calculate_order_financials(od.get("items", []), order_data=od, ord_rec=rec)
        total_customer_revenue += fin["actual_paid_amount"]
        total_factory_list += fin["factory_list_total"]
        total_factory_payable += fin["factory_payable_total"]

        for it in od.get("items", []):
            f_list, f_pay = get_item_factory_prices(it)
            key = (str(it.get("row_id", "")), bool(it.get("with_shim", False)))
            if key not in aggregated_map:
                aggregated_map[key] = {
                    "row_id": it.get("row_id", ""),
                    "wva": it.get("wva", ""),
                    "name": it.get("name", ""),
                    "base_name": it.get("base_name", it.get("name", "")),
                    "qty": int(it.get("qty", 0)),
                    "box_qty": it.get("box_qty") or get_box_qty_for_item(it.get("row_id", ""), it.get("name", "")),
                    "factory_unit_price": f_list,
                    "factory_payable_unit_price": f_pay,
                    "base_unit_price": f_list,
                    "unit_price": f_list,
                    "with_shim": bool(it.get("with_shim", False)),
                    "compatible_cars": it.get("compatible_cars") or get_compatible_vehicles_for_item(it.get("row_id", ""), it.get("name", "")),
                }
            else:
                aggregated_map[key]["qty"] += int(it.get("qty", 0))

    settlement_items = list(aggregated_map.values())
    settlement_order_data = {
        "doc_type": "فاکتور",
        "order_mode": "wholesale",
        "customer_title": f"تسویه کارخانه (شروین اکبری - سفارشات {', '.join(order_ids)})",
        "date": get_today_jalali(),
        "invoice_no": to_fa_num(batch_id),
        "items": settlement_items,
        "discount_type": "percent",
        "discount_value": FACTORY_DISCOUNT_PCT,
    }
    pdf_bytes = generate_pdf_bytes(settlement_order_data)
    total_factory_discount = max(0, total_factory_list - total_factory_payable)
    net_profit = total_customer_revenue - total_factory_payable
    carton_stats = calculate_order_cartons(settlement_items)

    summary = {
        "batch_id": batch_id,
        "order_ids": order_ids,
        "orders_count": len(selected_records),
        "total_sets": carton_stats["total_sets"],
        "carton_summary": carton_stats["summary_full"],
        "total_customer_revenue": total_customer_revenue,
        "total_factory_list": total_factory_list,
        "total_factory_discount": total_factory_discount,
        "total_factory_payable": total_factory_payable,
        "net_profit": net_profit,
    }
    return pdf_bytes, summary


