def enforce_wholesale_minimum_rule(order_data: dict, chat_id: int) -> str:
    order_mode = order_data.get("order_mode", get_user_order_mode(chat_id))
    total_qty = sum(i["qty"] for i in order_data.get("items", []))
    notice = ""

    order_data["warnings"] = [
        w for w in order_data.get("warnings", [])
        if "حداقل خرید عمده" not in w and "سفارش عمده محسوب" not in w and "حداقل استاندارد خرید عمده" not in w
    ]

    if order_data.get("force_wholesale"):
        order_data["order_mode"] = "wholesale"
        USER_ORDER_MODES[chat_id] = "wholesale"
        apply_order_mode_pricing_to_items(order_data["items"], order_mode="wholesale")
        return ""

    if order_mode == "wholesale" and 0 < total_qty < 15:
        order_data["order_mode"] = "retail"
        USER_ORDER_MODES[chat_id] = "retail"
        apply_order_mode_pricing_to_items(order_data["items"], order_mode="retail")
        notice = (
            f"⚠️ **توجه:** از آنجا که مجموع تعداد سفارش شما ({to_fa_num(total_qty)} دست) کمتر از ۱۵ دست است، "
            "**این سفارش، سفارش عمده محسوب نمی‌شود** و به حالت **«🛍 سفارش خرد»** تغییر یافت."
        )
        order_data["warnings"].append(
            f"به دلیل کمتر بودن تعداد از ۱۵ دست ({to_fa_num(total_qty)} دست)، این سفارش عمده محسوب نشده و به «سفارش خرد» تغییر یافت."
        )
    elif order_data.get("order_mode") == "wholesale" and 15 <= total_qty < 20:
        order_data["warnings"].append(
            f"حداقل استاندارد خرید عمده ۲ کارتن (۲۰ دست لنت) می‌باشد (جمع فعلی: {to_fa_num(total_qty)} دست)."
        )

    return notice


def format_draft_order_summary(order_data: dict, is_vip: bool = False) -> str:
    items = order_data.get("items", [])
    order_mode = order_data.get("order_mode", "wholesale")
    apply_order_mode_pricing_to_items(items, order_mode=order_mode)

    hide_prices = (order_mode == "wholesale") and (not is_vip)
    doc_label = order_data.get("doc_type", "پیش‌فاکتور") if is_vip else "پیش‌فاکتور"
    cust = order_data.get("customer_title", "مشتری گرامی")
    mode_label = get_order_mode_label(order_mode)

    header_lines = [
        f"🧾 **پیش‌نمایش اقلام {doc_label} سفارش {cust}**",
        f"🏷 **نوع سفارش:** `{mode_label}` | 📅 **تاریخ:** `{to_fa_num(order_data.get('date', get_today_jalali()))}`",
        "",
        f"📦 **لنت‌های تشخیص داده شده ({to_fa_num(len(items))} ردیف):**",
    ]

    fin = calculate_order_financials(items, order_data=order_data)
    total_qty = fin["total_qty"]
    subtotal = fin["subtotal"]
    discount_amount = fin["discount_amount"]
    discount_label = fin["discount_label"] or "تخفیف"
    total_payable = fin["total_payable"]
    carton_stats = calculate_order_cartons(items)
    compact_mode = len(items) > 18

    footer_lines = [""]
    footer_lines.append(f"📊 **جمع کل تعداد:** `{to_fa_num(total_qty)} دست` ({to_fa_num(len(items))} ردیف کالا)")
    footer_lines.append(f"📦 **محاسبه تعداد کارتن کیا:** `{carton_stats['summary_full']}`")
    if hide_prices:
        footer_lines.append("💡 _قیمت‌های سفارش عمده پس از تایید اقلام، در فایل «پیش‌فاکتور» درج و نمایش داده می‌شود._")
    else:
        if discount_amount > 0:
            footer_lines.append(f"💵 **جمع کل قبل از تخفیف:** `{to_fa_num(subtotal, comma=True)} ریال`")
            footer_lines.append(f"🎁 **{discount_label}:** `{to_fa_num(discount_amount, comma=True)} ریال`")
            footer_lines.append(f"💰 **مبلغ کل قابل پرداخت (پس از تخفیف):** `{to_fa_num(total_payable, comma=True)} ریال`")
        else:
            footer_lines.append(f"💰 **مبلغ کل قابل پرداخت:** `{to_fa_num(total_payable, comma=True)} ریال`")

    warnings = order_data.get("warnings") or []
    if warnings:
        footer_lines.append("\n⚠️ **تذکر:**")
        for w in warnings[:4]:
            footer_lines.append(f"• {w}")
        if len(warnings) > 4:
            footer_lines.append(f"• و {to_fa_num(len(warnings) - 4)} مورد دیگر...")

    footer_lines.append("\n❓ **آیا اقلام بالا مورد تایید است یا نیاز به اصلاح دارد؟**")
    footer_str = "\n".join(footer_lines)
    header_str = "\n".join(header_lines)

    max_items_chars = 3500 - len(header_str) - len(footer_str)
    item_lines = []
    used_chars = 0
    shown_count = 0

    for idx, it in enumerate(items, start=1):
        line_total = it["qty"] * it["unit_price"]
        shim_str = "با شیم" if it.get("with_shim") else "بدون شیم"
        bq = it.get("box_qty") or get_box_qty_for_item(it.get("row_id", ""), it.get("base_name", ""))
        c_info = format_item_carton_info(it["qty"], bq)
        if compact_mode:
            if hide_prices:
                entry = f"{to_fa_num(idx)}. {it['base_name']} ({shim_str}) | **{to_fa_num(it['qty'])} دست** ({c_info})"
            else:
                entry = f"{to_fa_num(idx)}. {it['base_name']} ({shim_str}) | **{to_fa_num(it['qty'])} دست** ({c_info}) | `{to_fa_num(line_total, comma=True)}`"
        else:
            if hide_prices:
                entry = (
                    f"{to_fa_num(idx)}. **{it['base_name']}** ({shim_str})\n"
                    f"   🔹 کد فنی: `{it['wva']}` | تعداد: **{to_fa_num(it['qty'])} دست** (`{c_info}`)"
                )
            else:
                entry = (
                    f"{to_fa_num(idx)}. **{it['base_name']}** ({shim_str})\n"
                    f"   🔹 کد: `{it['wva']}` | تعداد: **{to_fa_num(it['qty'])} دست** (`{c_info}`) | فی: `{to_fa_num(it['unit_price'], comma=True)}` | جمع: `{to_fa_num(line_total, comma=True)} ریال`"
                )

        if used_chars + len(entry) + 2 > max_items_chars:
            remaining = len(items) - shown_count
            item_lines.append(
                f"➕ **... و {to_fa_num(remaining)} ردیف دیگر** _(تمامی {to_fa_num(len(items))} ردیف به صورت کامل در فایل PDF درج می‌شوند)_"
            )
            break

        item_lines.append(entry)
        used_chars += len(entry) + 1
        shown_count += 1

    if not items:
        item_lines.append("⚠️ _در حال حاضر هیچ لنتی در لیست نیست. از دکمه اصلاح/اضافه کردن استفاده کنید._")

    return header_str + "\n" + "\n".join(item_lines) + "\n" + footer_str


