def get_draft_edit_list_keyboard(order_data: dict, is_vip: bool = False, page: int = 0) -> InlineKeyboardMarkup:
    items = order_data.get("items", [])
    page_size = 15
    total_pages = max(1, (len(items) + page_size - 1) // page_size)
    page = max(0, min(page, total_pages - 1))
    start_i = page * page_size
    end_i = min(len(items), start_i + page_size)

    buttons = []
    for idx in range(start_i, end_i):
        it = items[idx]
        shim_label = "با شیم" if it.get("with_shim") else "بدون شیم"
        btn_text = f"🔧 {to_fa_num(idx + 1)}. {it['base_name']} ({shim_label}) - {to_fa_num(it['qty'])} دست"
        buttons.append([InlineKeyboardButton(btn_text, callback_data=f"edit_item:{idx}")])

    if total_pages > 1:
        nav_row = []
        if page > 0:
            nav_row.append(InlineKeyboardButton("⬅️ صفحه قبل", callback_data=f"draft_edit_page:{page - 1}"))
        nav_row.append(InlineKeyboardButton(f"📄 صفحه {to_fa_num(page + 1)} از {to_fa_num(total_pages)}", callback_data="noop_page"))
        if page < total_pages - 1:
            nav_row.append(InlineKeyboardButton("➡️ صفحه بعد", callback_data=f"draft_edit_page:{page + 1}"))
