async def handle_excel_upload(update: Update, context: ContextTypes.DEFAULT_TYPE):
    doc = update.message.document
    chat_id = update.effective_chat.id
    user_id = update.effective_user.id if update.effective_user else chat_id

    # قابلیت بازیابی (Restore) فایل پشتیبان حسابداری (.json) توسط مدیر بدون از دست رفتن اطلاعات
    if user_id == ADMIN_TELEGRAM_ID and doc.file_name.lower().endswith(".json"):
        tmp_json = "/tmp/restore_accounting_backup.json"
        file = await context.bot.get_file(doc.file_id)
        await file.download_to_drive(tmp_json)
        try:
            load_accounting_db(custom_path=tmp_json, merge=True)
            await update.message.reply_text(
                f"✅ **فایل پشتیبان حسابداری با موفقیت بازیابی و ادغام شد!**\n\n"
                f"• تعداد کل سفارش‌ها در سیستم: `{to_fa_num(len(ACCOUNTING_ORDERS))} سفارش`\n"
                f"• تعداد مشتریان ثبت‌شده: `{to_fa_num(len(REGISTERED_CUSTOMERS))} مشتری`",
                parse_mode="Markdown",
            )
        except Exception as e:
            await update.message.reply_text(f"❌ خطا در بازیابی فایل پشتیبان: {e}")
        return

    active_oid = USER_ACTIVE_ORDER_ID.get(chat_id)
    if active_oid and active_oid in ACTIVE_PAYMENT_ORDERS:
        ord_rec = ACTIVE_PAYMENT_ORDERS[active_oid]
        if ord_rec.get("status") == "awaiting_receipt" and not doc.file_name.lower().endswith(".xlsx"):
            await forward_receipt_to_admin(update, context, ord_rec)
            return

    if not doc.file_name.lower().endswith(".xlsx"):
        await update.message.reply_text("⚠️ لطفاً فقط فایل اکسل با پسوند `.xlsx` ارسال کنید.")
        return

    file = await context.bot.get_file(doc.file_id)
    await file.download_to_drive(EXCEL_FILE_PATH)
    try:
        catalog = load_catalog_from_excel(EXCEL_FILE_PATH)
        await update.message.reply_text(
            f"✅ لیست قیمت اکسل با موفقیت بروزرسانی شد ({to_fa_num(len(catalog))} ردیف کالا بارگذاری شد)."
        )
    except Exception as e:
        await update.message.reply_text(f"❌ خطا در خواندن فایل اکسل: {e}")


async def send_vip_direct_invoice_pdf(
    chat_id: int,
    order_data: dict,
    context: ContextTypes.DEFAULT_TYPE,
    extra_note: str = None,
):
    global ORDER_COUNTER
    order_mode = order_data.get("order_mode", get_user_order_mode(chat_id))
    apply_order_mode_pricing_to_items(order_data["items"], order_mode=order_mode)

    oid = order_data.get("order_id")
    if not oid:
        ORDER_COUNTER += 1
        oid = str(ORDER_COUNTER)
        order_data["order_id"] = oid
    register_or_update_accounting_order(
        oid=str(oid),
        order_data=order_data,
        customer_chat_id=chat_id,
        default_acc_status="open",
    )

