def build_ask_customer_name_prompt_and_kb(user, page: int = 0) -> tuple:
    """
    منوی انتخاب مشتری حین ثبت سفارش:
    - اگر مدیر (ADMIN_TELEGRAM_ID) باشد: لیست مشتریان ثبت‌شده (نام و مغازه) + دکمه ثبت مشتری جدید + نام دلخواه را نشان می‌دهد.
    - برای سایر کاربران: امکان تایید نام تلگرام خودشان یا تایپ نام دلخواه.
    """
    uid = getattr(user, "id", 0) if user else 0
    tg_formatted = get_telegram_user_formatted_name(user)
    buttons = []

    if uid == ADMIN_TELEGRAM_ID and REGISTERED_CUSTOMERS:
        cust_list = sorted(REGISTERED_CUSTOMERS.values(), key=lambda c: int(str(c.get("id", "0"))) if str(c.get("id", "0")).isdigit() else 0, reverse=True)
        page_size = 8
        total_pages = max(1, (len(cust_list) + page_size - 1) // page_size)
        page = max(0, min(page, total_pages - 1))
        start_i = page * page_size
        end_i = min(len(cust_list), start_i + page_size)

        prompt_txt = (
            "👤 **انتخاب مشتری برای این سفارش:**\n\n"
            "👇 می‌توانید یکی از **مشتریان ثبت‌شده** زیر را انتخاب کنید، **مشتری جدید (نام و مغازه)** ثبت نمایید، و یا **نام دلخواه** را مستقیماً در چت تایپ و ارسال کنید:"
        )
        for c_rec in cust_list[start_i:end_i]:
            cid = c_rec["id"]
            buttons.append(
                [
                    InlineKeyboardButton(
                        f"👤 {c_rec['full_title']}",
                        callback_data=f"draft_pick_cust:{cid}",
                    )
                ]
            )
        if total_pages > 1:
            nav = []
            if page > 0:
                nav.append(InlineKeyboardButton("⬅️ قبلی", callback_data=f"draft_choose_customer:{page - 1}"))
            nav.append(InlineKeyboardButton(f"صفحه {to_fa_num(page + 1)}/{to_fa_num(total_pages)}", callback_data="noop_page"))
            if page < total_pages - 1:
                nav.append(InlineKeyboardButton("بعدی ➡️", callback_data=f"draft_choose_customer:{page + 1}"))
            buttons.append(nav)

        buttons.append(
            [
                InlineKeyboardButton(
                    "➕ ثبت مشتری جدید (نام و نام مغازه)",
                    callback_data="draft_reg_new_cust",
                )
            ]
        )
    else:
        if tg_formatted and not is_missing_customer_name(tg_formatted):
            prompt_txt = (
                "👤 **تعیین نام خریدار روی پیش‌فاکتور:**\n\n"
                "شما در متن سفارش، نامی برای پیش‌فاکتور ذکر نکرده‌اید.\n"
                f"❓ **آیا مایلید پیش‌فاکتور به نام خودتان (`{tg_formatted}`) صادر شود؟**\n\n"
                "👇 می‌توانید روی دکمه تایید زیر بزنید و یا **نام شخص / لوازم یدکی مورد نظر خود** را همین‌جا در چت تایپ و ارسال کنید:"
            )
            buttons.append(
                [
                    InlineKeyboardButton(
                        f"✅ بله، به نام خودم ({tg_formatted}) صادر شود",
                        callback_data="confirm_own_tg_name",
                    )
                ]
            )
        else:
            prompt_txt = (
                "👤 **تعیین نام خریدار روی پیش‌فاکتور:**\n\n"
                "شما در متن سفارش، نامی برای پیش‌فاکتور ذکر نکرده‌اید.\n"
                "✍️ **لطفاً نام و نام خانوادگی (یا نام لوازم یدکی) که می‌خواهید پیش‌فاکتور به نام او صادر شود را در چت تایپ و ارسال کنید:**"
            )
        if uid == ADMIN_TELEGRAM_ID:
            buttons.append(
                [
                    InlineKeyboardButton(
                        "➕ ثبت مشتری جدید (نام و نام مغازه)",
                        callback_data="draft_reg_new_cust",
                    )
                ]
            )

    buttons.append(
        [
            InlineKeyboardButton(
                "📄 صدور بدون نام («مشتری گرامی»)",
                callback_data="confirm_generic_name",
            )
        ]
    )
    buttons.append(
        [
            InlineKeyboardButton(
                "🔙 بازگشت به پیش‌نمایش سفارش",
                callback_data="draft_edit_menu",
            )
        ]
    )
    return prompt_txt, InlineKeyboardMarkup(buttons)


