def build_customers_menu_text_and_kb(page: int = 0) -> tuple:
    """
    منوی مدیریت مشتریان و گزارش میزان فروش، دریافتی واقعی، بدهی/بستانکاری و سود خالص هر مشتری
    (فقط سفارش‌های پرداخت‌شده جزو فروش و سود حساب می‌شوند).
    """
    sync_customers_from_existing_orders()
    cust_stats = compute_customer_sales_and_profit_stats(month_key="all")

    page_size = 8
    total_pages = max(1, (len(cust_stats) + page_size - 1) // page_size)
    page = max(0, min(page, total_pages - 1))
    start_i = page * page_size
    end_i = min(len(cust_stats), start_i + page_size)

    if not cust_stats:
        txt = (
            "👥 **دفترچه مشتریان و گزارش فروش/سود هر مشتری:**\n\n"
            "هنوز مشتری ثبت نشده است. با زدن دکمه **«➕ ثبت مشتری جدید (نام و مغازه)»** اولین مشتری را ثبت کنید."
        )
    else:
        lines = [
            f"👥 **لیست مشتریان و گزارش فروش و سود ({to_fa_num(len(cust_stats))} مشتری) — صفحه {to_fa_num(page + 1)} از {to_fa_num(total_pages)}:**\n"
            "_(توجه: فقط سفارش‌های پرداخت‌شده در میزان فروش و سود مشتری محاسبه شده‌اند)_\n"
        ]
        for idx, st in enumerate(cust_stats[start_i:end_i], start=start_i + 1):
            diff_str = ""
            if st["payment_diff_total"] != 0:
                diff_str = f" | {format_payment_diff_badge(st['payment_diff_total'])}"
            open_note = f" (+{to_fa_num(st['open_orders_count'])} پیش‌فاکتور باز)" if st["open_orders_count"] > 0 else ""
            lines.append(
                f"{to_fa_num(idx)}. 👤 **{st['customer_title']}**\n"
                f"   📦 خرید قطعی: `{to_fa_num(st['paid_orders_count'])} سفارش` (`{to_fa_num(st['total_sets'])} دست`){open_note}\n"
                f"   💵 کل پرداختی مشتری: `{to_fa_num(st['actual_paid_total'], comma=True)} ریال`{diff_str}\n"
                f"   💎 **سود خالص شما از این مشتری:** `{to_fa_num(st['net_profit'], comma=True)} ریال` (`{to_fa_num(st['net_profit'] // 10, comma=True)} تومان`)"
            )
        txt = "\n".join(lines)

    rows = [
        [
            InlineKeyboardButton(
                "➕ ثبت مشتری جدید (نام و نام مغازه)",
                callback_data="acc_add_cust",
            )
        ]
    ]
    for st in cust_stats[start_i:end_i]:
        cid = st.get("customer_id")
        if cid:
            rows.append(
                [
                    InlineKeyboardButton(
                        f"👤 {st['customer_title']} | سود: {to_fa_num(st['net_profit'] // 10, comma=True)} تومان",
                        callback_data=f"acc_view_cust:{cid}",
                    )
                ]
            )

    if total_pages > 1:
        nav = []
        if page > 0:
            nav.append(InlineKeyboardButton("⬅️ قبلی", callback_data=f"acc_menu_customers:{page - 1}"))
        nav.append(InlineKeyboardButton(f"صفحه {to_fa_num(page + 1)}/{to_fa_num(total_pages)}", callback_data="noop_page"))
        if page < total_pages - 1:
            nav.append(InlineKeyboardButton("بعدی ➡️", callback_data=f"acc_menu_customers:{page + 1}"))
        rows.append(nav)

    rows.append([InlineKeyboardButton("🔙 بازگشت به داشبورد حسابداری", callback_data="acc_dashboard")])
    return txt, InlineKeyboardMarkup(rows)


def build_single_customer_detail_text_and_kb(cid: str) -> tuple:
    """نمایش کاردکس مالی یک مشتری خاص شامل تمام سفارش‌های پرداخت‌شده، تراز پرداختی و سود خالص"""
    c_rec = REGISTERED_CUSTOMERS.get(str(cid))
    if not c_rec:
        return "⚠️ مشتری یافت نشد.", InlineKeyboardMarkup([[InlineKeyboardButton("🔙 بازگشت", callback_data="acc_menu_customers:0")]])

    full_title = c_rec["full_title"]
    paid_orders = []
    open_orders = []
    tot_sets = 0
    tot_invoiced = 0
    tot_paid = 0
    tot_fact = 0
    tot_profit = 0

    for rec in ACCOUNTING_ORDERS.values():
        od = rec.get("order_data") or {}
        if (od.get("customer_title") or "").strip() == full_title.strip():
            if rec.get("acc_status") == "open":
                open_orders.append(rec)
            else:
                paid_orders.append(rec)
                fin = calculate_order_financials(od.get("items", []), order_data=od, ord_rec=rec)
                tot_sets += fin["total_qty"]
                tot_invoiced += fin["total_payable"]
                tot_paid += fin["actual_paid_amount"]
                tot_fact += fin["factory_payable_total"]
                tot_profit += fin["net_profit"]

    diff_tot = tot_paid - tot_invoiced
    lines = [
        f"👤 **کاردکس مالی مشتری: {full_title}**",
        "━━━━━━━━━━━━━━━━━━━━",
        f"📦 **تعداد سفارشات پرداخت‌شده:** `{to_fa_num(len(paid_orders))} سفارش` (`{to_fa_num(tot_sets)} دست لنت`)",
        f"🧾 **جمع کل مبلغ فاکتورها:** `{to_fa_num(tot_invoiced, comma=True)} ریال`",
        f"💵 **جمع مبالغ واقعی پرداختی مشتری:** `{to_fa_num(tot_paid, comma=True)} ریال` (`{to_fa_num(tot_paid // 10, comma=True)} تومان`)",
        f"⚖️ **وضعیت تراز حساب مشتری:** `{format_payment_diff_badge(diff_tot)}`",
        f"🏭 **سهم کارخانه (با ۲۰٪ تخفیف):** `{to_fa_num(tot_fact, comma=True)} ریال`",
        f"💎 **سود خالص قطعی شما از این مشتری:** `{to_fa_num(tot_profit, comma=True)} ریال` (`{to_fa_num(tot_profit // 10, comma=True)} تومان`)",
    ]
    if open_orders:
        lines.append(f"📂 _پیش‌فاکتورهای باز (پرداخت‌نشده): `{to_fa_num(len(open_orders))} مورد` (در درآمد و سود بالا لحاظ نشده‌اند)_")

    if paid_orders:
        lines.append("━━━━━━━━━━━━━━━━━━━━")
        lines.append("📋 **آخرین سفارش‌های پرداخت‌شده این مشتری:**")
        for rec in paid_orders[:10]:
            oid = rec["order_id"]
            od = rec["order_data"]
            fin = calculate_order_financials(od["items"], order_data=od, ord_rec=rec)
            df_s = f" ({format_payment_diff_badge(fin['payment_diff'])})" if fin["payment_diff"] != 0 else ""
            lines.append(
                f"• `#{to_fa_num(oid)}` ({to_fa_num(od.get('date', ''))}) | پرداختی: `{to_fa_num(fin['actual_paid_amount'], comma=True)}`{df_s} | سود: `{to_fa_num(fin['net_profit'], comma=True)} ریال`"
            )

    kb_rows = [
        [
            InlineKeyboardButton(
                "📦 ثبت سفارش عمده جدید برای این مشتری",
                callback_data=f"pre_pick_cust:{cid}:wholesale",
            )
        ],
        [
            InlineKeyboardButton(
                "🛍 ثبت سفارش خرد جدید برای این مشتری",
                callback_data=f"pre_pick_cust:{cid}:retail",
            )
        ],
        [
            InlineKeyboardButton(
                "🗑 حذف نام مشتری از دفترچه",
                callback_data=f"acc_del_cust:{cid}",
            )
        ],
        [
            InlineKeyboardButton(
                "🔙 بازگشت به لیست مشتریان",
                callback_data="acc_menu_customers:0",
            )
        ],
    ]
    return "\n".join(lines), InlineKeyboardMarkup(kb_rows)


def build_monthly_stats_text_and_kb(month_key: str = "current") -> tuple:
    """
    بخش آمار و گزارش سود ماهانه:
    - فقط و فقط سفارش‌های پرداخت‌شده (paid_unsettled و settled_archived) جزو درآمد، فروش و سود ماهانه محسوب می‌شوند!
    - پیش‌فاکتورهایی که مشتری هنوز پرداخت نکرده (open) به هیچ عنوان جزو درآمد یا سود حساب نمی‌شوند.
    - شامل تفکیک میزان فروش و سود هر مشتری در همان ماه.
    """
    curr_ym = extract_jalali_year_month(get_today_jalali())
    if not month_key or month_key == "current":
        target_ym = curr_ym
    else:
        target_ym = month_key

    available_months = {curr_ym}
    filtered_records = []

    for rec in ACCOUNTING_ORDERS.values():
        od = rec.get("order_data", {})
        if not od.get("items"):
            continue
        ym = extract_jalali_year_month(od.get("date") or rec.get("created_at"))
        available_months.add(ym)
        if target_ym == "all" or ym == target_ym:
            filtered_records.append(rec)

    n_open = 0
    n_unsettled = 0
    n_archived = 0

    confirmed_sets = 0
    confirmed_items_all = []
    confirmed_invoiced_sum = 0
    confirmed_cust_revenue = 0   # مجموع مبالغ واقعی پرداخت‌شده توسط مشتریان
    confirmed_fact_list = 0
    confirmed_fact_discount = 0
    confirmed_fact_payable = 0
    confirmed_settled_fact = 0
    confirmed_unsettled_fact = 0
    confirmed_net_profit = 0

    for rec in filtered_records:
        st = rec.get("acc_status", "open")
        if st == "open":
            # پیش‌فاکتورهای پرداخت‌نشده به هیچ وجه جزو درآمد و سود حساب نمی‌شوند
            n_open += 1
            continue

        od = rec["order_data"]
        fin = calculate_order_financials(od["items"], order_data=od, ord_rec=rec)
        if st == "paid_unsettled":
            n_unsettled += 1
            confirmed_unsettled_fact += fin["factory_payable_total"]
        else:
            n_archived += 1
            confirmed_settled_fact += fin["factory_payable_total"]

        confirmed_sets += fin["total_qty"]
        confirmed_items_all.extend(od["items"])
        confirmed_invoiced_sum += fin["total_payable"]
        confirmed_cust_revenue += fin["actual_paid_amount"]
        confirmed_fact_list += fin["factory_list_total"]
        confirmed_fact_discount += fin["factory_discount_amount"]
        confirmed_fact_payable += fin["factory_payable_total"]
        confirmed_net_profit += fin["net_profit"]

    n_confirmed = n_unsettled + n_archived
    carton_stats = calculate_order_cartons(confirmed_items_all) if confirmed_items_all else {"summary_short": "۰ کارتن"}
    margin_pct = round((confirmed_net_profit / confirmed_cust_revenue) * 100.0, 1) if confirmed_cust_revenue > 0 else 0.0
    total_payment_diff = confirmed_cust_revenue - confirmed_invoiced_sum

    # آمار به تفکیک هر مشتری در این ماه (فقط سفارش‌های پرداخت‌شده)
    cust_month_stats = [
        c for c in compute_customer_sales_and_profit_stats(month_key=target_ym)
        if c["paid_orders_count"] > 0
    ]
    cust_breakdown_lines = []
    if cust_month_stats:
        cust_breakdown_lines.append("━━━━━━━━━━━━━━━━━━━━")
        cust_breakdown_lines.append("👥 **میزان فروش و سود به تفکیک هر مشتری (پرداخت‌شده‌ها):**")
        for idx, cs in enumerate(cust_month_stats[:12], start=1):
            df_badge = f" ({format_payment_diff_badge(cs['payment_diff_total'])})" if cs["payment_diff_total"] != 0 else ""
            cust_breakdown_lines.append(
                f"{to_fa_num(idx)}. **{cs['customer_title']}** ({to_fa_num(cs['paid_orders_count'])} سفارش = {to_fa_num(cs['total_sets'])} دست)\n"
                f"   💵 پرداختی: `{to_fa_num(cs['actual_paid_total'], comma=True)} ریال`{df_badge}\n"
                f"   💎 **سود خالص:** `{to_fa_num(cs['net_profit'], comma=True)} ریال` (`{to_fa_num(cs['net_profit'] // 10, comma=True)} تومان`)"
            )
        if len(cust_month_stats) > 12:
            cust_breakdown_lines.append(f"... و {to_fa_num(len(cust_month_stats) - 12)} مشتری دیگر (در منوی مشتریان قابل مشاهده است)")

    diff_line = ""
    if total_payment_diff != 0:
        diff_line = (
            f"🧾 جمع اسمی فاکتورها: `{to_fa_num(confirmed_invoiced_sum, comma=True)} ریال`\n"
            f"⚖️ تراز کسر/مازاد واریزی مشتریان: `{format_payment_diff_badge(total_payment_diff)}`\n"
        )

    period_title = format_jalali_month_title(target_ym)
    txt = (
        f"📊 **گزارش جامع آمار و سود — {period_title}**\n"
        "_(فقط سفارش‌های پرداخت‌شده؛ پیش‌فاکتورهای پرداخت‌نشده لحاظ نشده‌اند)_\n"
        "━━━━━━━━━━━━━━━━━━━━\n"
        f"✅ **تعداد سفارشات پرداخت‌شده این دوره:** `{to_fa_num(n_confirmed)} سفارش`\n"
        f"   ├ 💳 در انتظار تسویه با کارخانه: `{to_fa_num(n_unsettled)} سفارش`\n"
        f"   └ 🗄 تسویه‌شده با کارخانه (بایگانی): `{to_fa_num(n_archived)} سفارش`\n"
        f"📦 **حجم فروش قطعی:** `{to_fa_num(confirmed_sets)} دست لنت` (`{carton_stats['summary_short']}`)\n"
        "━━━━━━━━━━━━━━━━━━━━\n"
        f"{diff_line}"
        f"💵 **مجموع درآمد واقعی (دریافتی از مشتریان):**\n"
        f"   `{to_fa_num(confirmed_cust_revenue, comma=True)} ریال` (`{to_fa_num(confirmed_cust_revenue // 10, comma=True)} تومان`)\n"
        f"🏭 **مجموع به قیمت لیست کارخانه:** `{to_fa_num(confirmed_fact_list, comma=True)} ریال`\n"
        f"🎁 **مجموع ۲۰٪ تخفیف شما از کارخانه:** `{to_fa_num(confirmed_fact_discount, comma=True)} ریال`\n"
        f"💳 **مجموع سهم قابل پرداخت به کارخانه (با ۲۰٪ تخفیف):**\n"
        f"   `{to_fa_num(confirmed_fact_payable, comma=True)} ریال` (`{to_fa_num(confirmed_fact_payable // 10, comma=True)} تومان`)\n"
        f"   ├ تسویه‌شده با کارخانه: `{to_fa_num(confirmed_settled_fact, comma=True)} ریال`\n"
        f"   └ بدهی باقی‌مانده به کارخانه: `{to_fa_num(confirmed_unsettled_fact, comma=True)} ریال`\n"
        "━━━━━━━━━━━━━━━━━━━━\n"
        f"💎 **سود خالص قطعی شما در این ماه (حاشیه سود `{format_float_fa(margin_pct)}٪`):**\n"
        f"🌟 **`{to_fa_num(confirmed_net_profit, comma=True)} ریال`**\n"
        f"🌟 _(معادل **`{to_fa_num(confirmed_net_profit // 10, comma=True)} تومان`**)_\n"
        + ("\n" + "\n".join(cust_breakdown_lines) if cust_breakdown_lines else "")
    )

    rows = []
    base_nav_ym = curr_ym if target_ym == "all" else target_ym
    prev_ym = shift_jalali_year_month(base_nav_ym, -1)
    next_ym = shift_jalali_year_month(base_nav_ym, +1)
    rows.append(
        [
            InlineKeyboardButton(f"⬅️ ماه قبل ({to_fa_num(prev_ym)})", callback_data=f"acc_menu_stats:{prev_ym}"),
            InlineKeyboardButton(f"ماه بعد ({to_fa_num(next_ym)}) ➡️", callback_data=f"acc_menu_stats:{next_ym}"),
        ]
    )

    for i in range(1, 6):
        available_months.add(shift_jalali_year_month(curr_ym, -i))
    sorted_months = sorted(available_months, reverse=True)[:6]
    m_btns = []
    for ym in sorted_months:
        mark = "✅ " if ym == target_ym else ""
        try:
            p = ym.split("/")
            lbl = f"{mark}{JALALI_MONTH_NAMES.get(int(p[1]), p[1])} {to_fa_num(p[0])}"
        except Exception:
            lbl = f"{mark}{to_fa_num(ym)}"
        m_btns.append(InlineKeyboardButton(lbl, callback_data=f"acc_menu_stats:{ym}"))
        if len(m_btns) == 2:
            rows.append(m_btns)
            m_btns = []
    if m_btns:
        rows.append(m_btns)

    all_mark = "✅ " if target_ym == "all" else ""
    rows.append(
        [
            InlineKeyboardButton(f"{all_mark}📊 نمایش آمار تجمیعی کل ماه‌ها", callback_data="acc_menu_stats:all"),
            InlineKeyboardButton("📅 ماه جاری", callback_data="acc_menu_stats:current"),
        ]
    )
    rows.append(
        [
            InlineKeyboardButton("👥 مشاهده کامل گزارش تک‌تک مشتریان", callback_data="acc_menu_customers:0")
        ]
    )
    rows.append([InlineKeyboardButton("🔙 بازگشت به داشبورد حسابداری", callback_data="acc_dashboard")])
    return txt, InlineKeyboardMarkup(rows)


async def accounting_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """دستور /accounting ویژه مدیر جهت باز کردن پنل حسابداری"""
    user_id = update.effective_user.id if update.effective_user else 0
    if user_id != ADMIN_TELEGRAM_ID:
        await update.message.reply_text("⛔ بخش حسابداری منحصراً در اختیار مدیر سیستم است.")
        return
    txt, kb = build_accounting_dashboard_text_and_kb()
    await update.message.reply_text(txt, parse_mode="Markdown", reply_markup=kb)


async def handle_text_order(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global RUNTIME_PAYMENT_BANK_INFO
    user_text = update.message.text.strip()
    chat_id = update.effective_chat.id
    user_id = update.effective_user.id if update.effective_user else chat_id

    # ۰. بررسی اینکه آیا مدیر اصلی (ADMIN_TELEGRAM_ID) در حال وارد کردن «تخفیف درصدی/مبلغی»، «توضیحات زمان تحویل» یا «شماره کارت سفارشی» است
    if user_id == ADMIN_TELEGRAM_ID and chat_id in ADMIN_STATE:
        adm_st = ADMIN_STATE.get(chat_id)
        st_mode = adm_st.get("mode")
        oid = adm_st.get("order_id")

        # ثبت مشتری جدید (نام و نام مغازه) توسط مدیر
        if st_mode in ("awaiting_new_customer_reg", "awaiting_new_customer_for_draft", "awaiting_new_customer_pre_order"):
            ADMIN_STATE.pop(chat_id, None)
            c_rec = parse_and_register_customer_text(user_text, save_now=True)
            if not c_rec:
                await update.message.reply_text("⚠️ نام واردشده معتبر نبود. لطفاً مجدداً نام مشتری و نام مغازه را وارد کنید:")
                return
            full_title = c_rec["full_title"]
            if st_mode == "awaiting_new_customer_reg":
                txt_c, kb_c = build_customers_menu_text_and_kb(page=0)
                await update.message.reply_text(
                    f"✅ **مشتری جدید با موفقیت ثبت شد:** `{full_title}`\n\n{txt_c}",
                    parse_mode="Markdown",
                    reply_markup=kb_c,
                )
                return
            elif st_mode == "awaiting_new_customer_pre_order":
                order_mode = adm_st.get("order_mode", get_user_order_mode(chat_id))
                PRE_SELECTED_ORDER_CUSTOMER[chat_id] = full_title
                await update.message.reply_text(
                    f"✅ مشتری **`{full_title}`** در لیست مشتریان ثبت و برای سفارش فعلی انتخاب شد!\n\n"
                    f"حالا لطفاً لیست لنت‌های سفارش ({get_order_mode_label(order_mode)}) را به صورت **متن، ویس یا عکس** ارسال فرمایید:",
                    parse_mode="Markdown",
                )
                return
            elif st_mode == "awaiting_new_customer_for_draft":
                draft = PENDING_DRAFT_ORDERS.get(chat_id)
                if not draft:
                    await update.message.reply_text(f"✅ مشتری **`{full_title}`** ثبت شد.", parse_mode="Markdown")
                    return
                draft["customer_title"] = full_title
                draft["name_confirmed"] = True
                await update.message.reply_text(
                    f"✅ مشتری **`{full_title}`** در دفترچه مشتریان ثبت شد و روی سفارش قرار گرفت!\n\n"
                    + format_draft_order_summary(draft, is_vip=True),
                    parse_mode="Markdown",
                    reply_markup=get_draft_summary_keyboard(is_vip=True, order_data=draft, user_id=user_id),
                )
                return

        # ثبت مبلغ واقعی پرداخت‌شده توسط مشتری (کمتر، بیشتر یا برابر مبلغ فاکتور)
        if st_mode == "awaiting_paid_amount":
            rec = ACCOUNTING_ORDERS.get(str(oid))
            if not rec:
                ADMIN_STATE.pop(chat_id, None)
                await update.message.reply_text("⚠️ این سفارش در حافظه یافت نشد.")
                return
            try:
                paid_val = parse_money_input_rials(user_text)
            except ValueError as ve:
                await update.message.reply_text(f"⚠️ {ve}\nلطفاً مبلغ پرداختی مشتری را به ریال (یا با ذکر کلمه تومان) وارد کنید:")
                return

            ADMIN_STATE.pop(chat_id, None)
            was_open = rec.get("acc_status", "open") == "open"
            if was_open:
                rec["acc_status"] = "paid_unsettled"
                rec["paid_at"] = get_today_jalali()
                rec["order_data"]["doc_type"] = "فاکتور"
                ADMIN_SELECTED_SETTLE_OIDS.add(str(oid))
            rec["actual_paid_amount"] = paid_val
            rec["order_data"]["actual_paid_amount"] = paid_val
            save_accounting_db()

            fin = calculate_order_financials(rec["order_data"]["items"], order_data=rec["order_data"], ord_rec=rec)
            diff_badge = format_payment_diff_badge(fin["payment_diff"])
            await update.message.reply_text(
                f"✅ **مبلغ پرداختی مشتری برای سفارش `#{to_fa_num(oid)}` ({rec['order_data'].get('customer_title', '')}) ثبت شد!**\n\n"
                f"🧾 مبلغ فاکتور: `{to_fa_num(fin['total_payable'], comma=True)} ریال`\n"
                f"💵 **مبلغ واقعی پرداختی مشتری:** `{to_fa_num(fin['actual_paid_amount'], comma=True)} ریال` (`{to_fa_num(fin['actual_paid_amount'] // 10, comma=True)} تومان`)\n"
                f"⚖️ **وضعیت واریزی:** `{diff_badge}`\n"
                f"💳 **سهم کارخانه (با ۲۰٪ تخفیف):** `{to_fa_num(fin['factory_payable_total'], comma=True)} ریال`\n"
                f"💎 **سود خالص واقعی شما از این سفارش:** `{to_fa_num(fin['net_profit'], comma=True)} ریال` (`{to_fa_num(fin['net_profit'] // 10, comma=True)} تومان`)",
                parse_mode="Markdown",
                reply_markup=InlineKeyboardMarkup(
                    [
                        [InlineKeyboardButton("💳 مشاهده سفارشات تسویه‌نشده با کارخانه", callback_data="acc_menu_unsettled:0")],
                        [InlineKeyboardButton("📂 بازگشت به سفارش‌های باز", callback_data="acc_menu_open:0")],
                        [InlineKeyboardButton("💼 داشبورد حسابداری", callback_data="acc_dashboard")],
                    ]
                ),
            )
            return

        if st_mode in ("awaiting_vip_discount_percent", "awaiting_vip_discount_amount"):
            order_data = LAST_ORDERS.get(chat_id)
            if not order_data:
                ADMIN_STATE.pop(chat_id, None)
                await update.message.reply_text("⚠️ سفارش فعلی در حافظه یافت نشد.")
                return
            subtotal = sum(int(i["qty"]) * int(i["unit_price"]) for i in order_data["items"])
            disc_mode = "percent" if st_mode == "awaiting_vip_discount_percent" else "amount"
            try:
                d_type, d_val = parse_admin_discount_input(user_text, disc_mode, subtotal)
            except ValueError as ve:
                await update.message.reply_text(f"⚠️ {ve}\nلطفاً مجدداً عدد را ارسال کنید:")
                return
            ADMIN_STATE.pop(chat_id, None)
            order_data["discount_type"] = d_type
            order_data["discount_value"] = d_val
            await update.message.reply_text("✅ تخفیف اعمال شد. در حال صدور مجدد فایل PDF...")
            await send_vip_direct_invoice_pdf(chat_id, order_data, context)
            return

        ord_rec = ACTIVE_PAYMENT_ORDERS.get(oid)
        if not ord_rec:
            ADMIN_STATE.pop(chat_id, None)
            await update.message.reply_text("⚠️ این سفارش در حافظه یافت نشد.")
            return

        if st_mode in ("awaiting_discount_percent", "awaiting_discount_amount"):
            order_data = ord_rec["order_data"]
            subtotal = sum(int(i["qty"]) * int(i["unit_price"]) for i in order_data["items"])
            disc_mode = "percent" if st_mode == "awaiting_discount_percent" else "amount"
            try:
                d_type, d_val = parse_admin_discount_input(user_text, disc_mode, subtotal)
            except ValueError as ve:
                await update.message.reply_text(f"⚠️ {ve}\nلطفاً مجدداً عدد را ارسال کنید:")
                return

            ADMIN_STATE.pop(chat_id, None)
            order_data["discount_type"] = d_type
            order_data["discount_value"] = d_val
            order_data["doc_type"] = "پیش‌فاکتور"
            register_or_update_accounting_order(oid, order_data, ord_rec.get("customer_chat_id", chat_id))

            wait_disc = await update.message.reply_text("⏳ در حال اعمال تخفیف و بروزرسانی فایل پیش‌فاکتور...")
            try:
                pdf_bytes = generate_pdf_bytes(order_data)
                cust = order_data["customer_title"]
                admin_caption = build_admin_proforma_caption(oid, ord_rec)
                admin_kb = build_admin_proforma_keyboard(oid, order_data)
                await context.bot.send_document(
                    chat_id=chat_id,
                    document=io.BytesIO(pdf_bytes),
                    filename=f"پیش‌فاکتور تخفیف‌دار {cust} - کد {oid}.pdf",
                    caption=admin_caption,
                    parse_mode="Markdown",
                    reply_markup=admin_kb,
                )
                await wait_disc.delete()
            except Exception as e:
                logger.exception("Error regenerating discounted proforma")
                await wait_disc.edit_text(f"❌ خطا در بروزرسانی پیش‌فاکتور: `{e}`", parse_mode="Markdown")
            return

        ADMIN_STATE.pop(chat_id, None)

        if st_mode == "awaiting_custom_bank":
            RUNTIME_PAYMENT_BANK_INFO = user_text
            cust_chat_id = ord_rec["customer_chat_id"]
            ord_rec["status"] = "awaiting_receipt"
            USER_ACTIVE_ORDER_ID[cust_chat_id] = oid
            order_data = ord_rec["order_data"]
            fin = calculate_order_financials(order_data["items"], order_data=order_data)
            subtotal = fin["subtotal"]
            discount_amount = fin["discount_amount"]
            discount_label = fin["discount_label"] or "تخفیف"
            total_payable = fin["total_payable"]

            if discount_amount > 0 or order_data.get("admin_modified_pricing"):
                try:
                    order_data["doc_type"] = "پیش‌فاکتور"
                    disc_pdf = generate_pdf_bytes(order_data)
                    mode_note = "با قیمت عمده" if order_data.get("order_mode") == "wholesale" and order_data.get("admin_modified_pricing") else ""
                    cap_parts = [p for p in [mode_note, f"با اعمال {discount_label}" if discount_amount > 0 else ""] if p]
                    cap_suffix = " و ".join(cap_parts) if cap_parts else "اصلاح‌شده"
                    await context.bot.send_document(
                        chat_id=cust_chat_id,
                        document=io.BytesIO(disc_pdf),
                        filename=f"پیش‌فاکتور جدید سفارش {order_data['customer_title']}.pdf",
                        caption=f"📄 **نسخه جدید پیش‌فاکتور شما ({cap_suffix}) تاییدشده توسط مدیریت**",
                        parse_mode="Markdown",
                    )
                except Exception as e_pdf:
                    logger.warning(f"Could not send updated PDF to customer: {e_pdf}")

            if discount_amount > 0:
                price_summary = (
                    f"💵 **مبلغ قبل از تخفیف:** `{to_fa_num(subtotal, comma=True)} ریال`\n"
                    f"🎁 **{discount_label} مدیریت:** `{to_fa_num(discount_amount, comma=True)} ریال`\n"
                    f"💰 **مبلغ نهایی قابل پرداخت:** `{to_fa_num(total_payable, comma=True)} ریال`"
                )
            else:
                price_summary = f"💰 **مبلغ قابل پرداخت:** `{to_fa_num(total_payable, comma=True)} ریال`"

            await context.bot.send_message(
                chat_id=cust_chat_id,
                text=(
                    f"✅ **پیش‌فاکتور سفارش `#{to_fa_num(oid)}` شما توسط مدیریت تایید شد!**\n\n"
                    f"{price_summary}\n\n"
                    f"💳 **اطلاعات حساب و شماره کارت جهت واریز:**\n{user_text}\n\n"
                    "📸 **لطفاً پس از واریز وجه، تصویر رسید پرداخت خود را در همین چت ارسال فرمایید تا فاکتور نهایی و زمان تحویل برایتان صادر شود.**"
                ),
                parse_mode="Markdown",
            )
            await update.message.reply_text(
                f"✅ اطلاعات پرداخت برای مشتری (`{ord_rec['order_data']['customer_title']}`) ارسال شد و سیستم منتظر دریافت رسید از مشتری است.",
                parse_mode="Markdown",
            )
            return

        elif st_mode == "awaiting_delivery_note":
            delivery_note = user_text
            cust_chat_id = ord_rec["customer_chat_id"]
            order_data = ord_rec["order_data"]
            order_data["doc_type"] = "فاکتور"
            ord_rec["status"] = "completed"
            if ord_rec.get("acc_status", "open") == "open":
                ord_rec["acc_status"] = "paid_unsettled"
                ord_rec["paid_at"] = get_today_jalali()
            if ord_rec.get("actual_paid_amount") is None:
                fin_tmp = calculate_order_financials(order_data["items"], order_data=order_data, ord_rec=ord_rec)
                ord_rec["actual_paid_amount"] = fin_tmp["total_payable"]
                order_data["actual_paid_amount"] = fin_tmp["total_payable"]
            ACCOUNTING_ORDERS[str(oid)] = ord_rec
            save_accounting_db()
            USER_ACTIVE_ORDER_ID.pop(cust_chat_id, None)

            wait_adm = await update.message.reply_text("⏳ در حال صدور و ارسال فاکتور نهایی برای مشتری...")
            try:
                pdf_bytes = generate_pdf_bytes(order_data)
                cust = order_data["customer_title"]
                filename = f"فاکتور سفارش {cust}.pdf"
                fin = calculate_order_financials(order_data["items"], order_data=order_data)
                total_payable = fin["total_payable"]
                total_qty = fin["total_qty"]
                disc_amt = fin["discount_amount"]
                disc_lbl = fin["discount_label"] or "تخفیف"
                disc_line = f"🎁 {disc_lbl}: `{to_fa_num(disc_amt, comma=True)} ریال`\n" if disc_amt > 0 else ""

                final_caption = (
                    f"🎉 **فاکتور نهایی سفارش {cust}** (تسویه شده)\n"
                    f"🔢 کد سفارش: `#{to_fa_num(oid)}`\n"
                    f"📅 تاریخ: `{to_fa_num(order_data['date'])}`\n"
                    f"📦 تعداد کل: `{to_fa_num(total_qty)}` دست\n"
                    f"{disc_line}"
                    f"💰 مبلغ کل: `{to_fa_num(total_payable, comma=True)} ریال`\n\n"
                    f"🚚 **توضیحات مدیریت بابت زمان و نحوه تحویل بار:**\n"
                    f"« {delivery_note} »\n\n"
                    "🙏 با تشکر از خرید و اعتماد شما به **شرکت کیالنت البرز نور**"
                )
                await context.bot.send_document(
                    chat_id=cust_chat_id,
                    document=io.BytesIO(pdf_bytes),
                    filename=filename,
                    caption=final_caption,
                    parse_mode="Markdown",
                )
                await wait_adm.edit_text(
                    f"✅ **فاکتور نهایی سفارش `#{to_fa_num(oid)}`** به همراه توضیحات زمان تحویل با موفقیت برای مشتری (`{cust}`) ارسال شد!",
                    parse_mode="Markdown",
                )
            except Exception as e:
                logger.exception("Error sending final invoice to customer")
                await wait_adm.edit_text(f"❌ خطا در ارسال فاکتور نهایی به مشتری: `{e}`", parse_mode="Markdown")
            return

    # ۱. بررسی کلیک روی دکمه «🔐 وارد کردن رمز» یا ارسال رمز ۵ رقمی در حالت انتظار
    if user_text in (BTN_VIP_CODE_TEXT, "🔓 حالت ویژه فعال است", "رمز", "وارد کردن رمز"):
        expected_code = get_expected_vip_code(user_id)
        if is_user_vip(user_id):
            await update.message.reply_text(
                "🔓 **حالت ویژه (صدور مستقیم فاکتور و پیش‌فاکتور بدون نیاز به پرداخت) برای شما فعال است!**\n"
                "می‌توانید مستقیماً سفارش خود را بفرستید.",
                parse_mode="Markdown",
                reply_markup=get_main_reply_keyboard(user_id=user_id),
            )
            return
        AWAITING_VIP_CODE_USERS.add(chat_id)
        await update.message.reply_text(
            "🔐 **ورود به بخش صدور مستقیم فاکتور:**\n\n"
            "لطفاً **رمز ۵ رقمی اختصاصی** خود را وارد نمایید:",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup(
                [[InlineKeyboardButton("🏠 انصراف و بازگشت به منوی اصلی", callback_data="back_to_main_menu")]]
            ),
        )
        return

    if chat_id in AWAITING_VIP_CODE_USERS:
        entered = to_en_str(user_text).strip()
        expected = get_expected_vip_code(user_id)
        if entered == expected:
            AWAITING_VIP_CODE_USERS.discard(chat_id)
            VIP_UNLOCKED_USERS.add(user_id)
            await update.message.reply_text(
                "✅ **رمز صحیح است! دسترسی ویژه برای شما فعال شد.**\n\n"
                "از این لحظه:\n"
                "• می‌توانید مستقیماً **فاکتور** و **پیش‌فاکتور** را بدون مراحل پرداخت و تایید دریافت کنید.\n"
                "• قیمت‌های سفارش عمده نیز در پیش‌نمایش برای شما نمایش داده می‌شود.",
                parse_mode="Markdown",
                reply_markup=get_main_reply_keyboard(user_id=user_id),
            )
            return
        else:
            await update.message.reply_text(
                "❌ **رمز وارد شده اشتباه است.** لطفاً مجدداً رمز ۵ رقمی را وارد کنید یا به منوی اصلی بازگردید:",
                parse_mode="Markdown",
                reply_markup=InlineKeyboardMarkup(
                    [[InlineKeyboardButton("🏠 بازگشت به منوی اصلی", callback_data="back_to_main_menu")]]
                ),
            )
            return

    # ۱.۵ بررسی کلیک روی دکمه «💼 بخش حسابداری (ویژه مدیر)»
    if user_text in (BTN_ACCOUNTING_TEXT, "حسابداری", "بخش حسابداری", "پنل حسابداری"):
        if user_id != ADMIN_TELEGRAM_ID:
            await update.message.reply_text("⛔ بخش حسابداری منحصراً در اختیار مدیر سیستم است.")
            return
        USER_EDIT_STATE.pop(chat_id, None)
        ADMIN_STATE.pop(chat_id, None)
        AWAITING_QUESTION_MODE.discard(chat_id)
        txt, kb = build_accounting_dashboard_text_and_kb()
        await update.message.reply_text(txt, parse_mode="Markdown", reply_markup=kb)
        return

    # ۲. بررسی کلیک روی دکمه «سفارش عمده»
    if user_text in (BTN_WHOLESALE_TEXT, "سفارش عمده", "عمده"):
        USER_ORDER_MODES[chat_id] = "wholesale"
        AWAITING_QUESTION_MODE.discard(chat_id)
        USER_EDIT_STATE.pop(chat_id, None)
        ADMIN_STATE.pop(chat_id, None)
        if user_id == ADMIN_TELEGRAM_ID:
            sel_c = PRE_SELECTED_ORDER_CUSTOMER.get(chat_id)
            sel_line = f"\n👤 **مشتری انتخاب‌شده فعلی:** `{sel_c}`\n" if sel_c else ""
            await update.message.reply_text(
                "✅ بخش **«📦 سفارش عمده»** انتخاب شد."
                f"{sel_line}\n"
                "👇 **می‌توانید ابتدا مشتری را از لیست زیر انتخاب کنید (یا مشتری جدید ثبت نمایید)، و یا مستقیماً متن، ویس یا عکس سفارش را بفرستید:**",
                parse_mode="Markdown",
                reply_markup=build_pre_order_customer_picker_kb("wholesale", page=0),
            )
            return
        await update.message.reply_text(
            "✅ بخش **«📦 سفارش عمده»** انتخاب شد.\n"
            "📌 **توجه:**\n"
            "• **حداقل خرید عمده، ۲ کارتن یا معادل ۲۰ دست لنت می‌باشد** (سفارش‌های کمتر از ۱۵ دست، سفارش عمده محسوب نمی‌شوند و به سفارش خرد منتقل می‌شوند).\n"
            "• **تمامی سفارشات به صورت نقدی تسویه می‌شوند.**\n\n"
            "حالا می‌توانید سفارش خود را به صورت **متن، ویس یا عکس** ارسال فرمایید.",
            parse_mode="Markdown",
            reply_markup=get_main_reply_keyboard(user_id=user_id),
        )
        return

    # ۳. بررسی کلیک روی دکمه «سفارش خرد»
    if user_text in (BTN_RETAIl_TEXT, "سفارش خرد", "خرد"):
        USER_ORDER_MODES[chat_id] = "retail"
        AWAITING_QUESTION_MODE.discard(chat_id)
        USER_EDIT_STATE.pop(chat_id, None)
        ADMIN_STATE.pop(chat_id, None)
        if user_id == ADMIN_TELEGRAM_ID:
            sel_c = PRE_SELECTED_ORDER_CUSTOMER.get(chat_id)
            sel_line = f"\n👤 **مشتری انتخاب‌شده فعلی:** `{sel_c}`\n" if sel_c else ""
            await update.message.reply_text(
                "✅ بخش **«🛍 سفارش خرد»** انتخاب شد."
                f"{sel_line}\n"
                "👇 **می‌توانید ابتدا مشتری را از لیست زیر انتخاب کنید (یا مشتری جدید ثبت نمایید)، و یا مستقیماً متن، ویس یا عکس سفارش را بفرستید:**",
                parse_mode="Markdown",
                reply_markup=build_pre_order_customer_picker_kb("retail", page=0),
            )
            return
        await update.message.reply_text(
            "✅ بخش **«🛍 سفارش خرد»** انتخاب شد.\n"
            "📌 **توجه:** **تمامی سفارشات به صورت نقدی تسویه می‌شوند.**\n\n"
            "حالا می‌توانید سفارش خود را به صورت **متن، ویس یا عکس** ارسال فرمایید.",
            parse_mode="Markdown",
            reply_markup=get_main_reply_keyboard(user_id=user_id),
        )
        return

    # ۴. بررسی کلیک روی دکمه «اگر سوالی داری ازم بپرس»
    if user_text in (BTN_ASK_QUESTION_TEXT, "سوال", "سوال فنی", "اشتراکات لنت"):
        AWAITING_QUESTION_MODE.add(chat_id)
        USER_EDIT_STATE.pop(chat_id, None)
        await update.message.reply_text(
            "💬 **مشاور فنی و راهنمای کاتالوگ کیالنت البرز نور آماده پاسخگویی است!**\n\n"
            "هر سوالی دارید بپرسید؛ برای مثال:\n"
            "• _«چه لنت‌هایی تولید می‌کنید؟»_\n"
            "• _«لنت جلو جک S5 یا شاهین به چه ماشین‌های دیگه‌ای می‌خوره؟»_\n"
            "• _«برای پژو ۲۰۷ یا تیگو ۷ چه لنتی دارید و اشتراکاتش چیه؟»_\n\n"
            "✍️ لطفاً سوال خود را تایپ کنید:",
            parse_mode="Markdown",
            reply_markup=get_main_reply_keyboard(user_id=user_id),
        )
        return

    # ۴.۵ بررسی اینکه آیا مشتری در مرحله ارسال رسید پرداخت (awaiting_receipt) پیام متنی فرستاده است
    active_oid = USER_ACTIVE_ORDER_ID.get(chat_id)
    if active_oid and active_oid in ACTIVE_PAYMENT_ORDERS:
        ord_rec = ACTIVE_PAYMENT_ORDERS[active_oid]
        if ord_rec.get("status") == "awaiting_receipt" and chat_id not in USER_EDIT_STATE and chat_id not in AWAITING_QUESTION_MODE:
            await forward_receipt_to_admin(update, context, ord_rec)
            return

    # ۵. بررسی اینکه آیا کاربر در حال وارد کردن «عدد دلخواه تعداد» یا «افزودن لنت جدید» در منوی اصلاح است
    edit_state = USER_EDIT_STATE.get(chat_id)
    if edit_state and chat_id in PENDING_DRAFT_ORDERS:
        draft = PENDING_DRAFT_ORDERS[chat_id]
        state_mode = edit_state.get("mode")
        vip_flag = is_user_vip(user_id)
        hide_prices = (draft.get("order_mode") == "wholesale") and (not vip_flag)

        if state_mode == "awaiting_customer_name":
            USER_EDIT_STATE.pop(chat_id, None)
            draft = PENDING_DRAFT_ORDERS.pop(chat_id, None)
            if not draft or not draft.get("items"):
                await update.message.reply_text("⚠️ سفارش فعلی یافت نشد. لطفاً مجدداً سفارش را بفرستید.")
                return
            draft["customer_title"] = parse_typed_customer_name(user_text)
            draft["name_confirmed"] = True
            auto_notice = enforce_wholesale_minimum_rule(draft, chat_id)
            LAST_ORDERS[chat_id] = draft
            if vip_flag:
                wait_pdf = await update.message.reply_text(
                    f"⏳ در حال صدور {draft.get('doc_type', 'پیش‌فاکتور')} به نام **{draft['customer_title']}**...",
                    parse_mode="Markdown",
                )
                try:
                    await send_vip_direct_invoice_pdf(
                        chat_id, draft, context, extra_note=draft.get("extra_note")
                    )
                    await wait_pdf.delete()
                except Exception as e:
                    await wait_pdf.edit_text(f"❌ خطا در ساخت PDF:\n`{e}`", parse_mode="Markdown")
            else:
                wait_pdf = await update.message.reply_text(
                    f"⏳ در حال صدور پیش‌فاکتور رسمی به نام **{draft['customer_title']}**...",
                    parse_mode="Markdown",
                )
                try:
                    await send_customer_proforma_pdf(
                        chat_id,
                        draft,
                        context,
                        extra_note=draft.get("extra_note"),
                        auto_switched_notice=auto_notice,
                    )
                    await wait_pdf.delete()
                except Exception as e:
                    await wait_pdf.edit_text(f"❌ خطا در ساخت پیش‌فاکتور:\n`{e}`", parse_mode="Markdown")
            return

        if state_mode == "awaiting_qty":
            idx = edit_state.get("item_idx", 0)
            en_txt = to_en_str(user_text).strip()
            m_num = re.search(r"(\d+)", en_txt)
            if m_num and 0 <= idx < len(draft["items"]):
                new_qty = max(1, int(m_num.group(1)))
                draft["items"][idx]["qty"] = new_qty
                USER_EDIT_STATE.pop(chat_id, None)
                catalog = load_catalog_from_excel(EXCEL_FILE_PATH)
                has_5_6, _, _ = has_two_backing_plate_models(draft["items"][idx]["row_id"], catalog)
                await update.message.reply_text(
                    f"✅ تعداد ردیف {to_fa_num(idx + 1)} به **{to_fa_num(new_qty)} دست** تغییر یافت.\n\n"
                    + format_single_item_edit_text(draft["items"][idx], idx, len(draft["items"]), has_5_6, hide_prices=hide_prices),
                    parse_mode="Markdown",
                    reply_markup=get_single_item_edit_keyboard(draft["items"][idx], idx, catalog, is_vip=vip_flag),
                )
                return
            else:
                await update.message.reply_text("⚠️ لطفاً فقط یک عدد معتبر (مثلاً `5` یا `10`) ارسال کنید:")
                return

        elif state_mode == "awaiting_add_item":
            USER_EDIT_STATE.pop(chat_id, None)
            order_mode = draft.get("order_mode", get_user_order_mode(chat_id))
            wait_add = await update.message.reply_text("⏳ در حال شناسایی لنت جدید و افزودن به لیست...")
            try:
                catalog = load_catalog_from_excel(EXCEL_FILE_PATH)
                new_parsed = extract_order_from_text(user_text, catalog, order_mode=order_mode)
                added_items = new_parsed.get("items", [])
                if not added_items:
                    await wait_add.edit_text(
                        "⚠️ لنتی از متن شما تشخیص داده نشد. لطفاً دوباره از منوی زیر امتحان کنید:",
                        reply_markup=get_draft_edit_list_keyboard(draft, is_vip=vip_flag),
                    )
                    return
                draft["items"].extend(added_items)
                await wait_add.edit_text(
                    f"✅ **{to_fa_num(len(added_items))} ردیف لنت جدید** به سفارش اضافه شد!\n\n"
                    + format_draft_order_summary(draft, is_vip=vip_flag),
                    parse_mode="Markdown",
                    reply_markup=get_draft_edit_list_keyboard(draft, is_vip=vip_flag),
                )
            except Exception as e:
                await wait_add.edit_text(
                    f"❌ خطا در افزودن لنت: `{e}`",
                    parse_mode="Markdown",
                    reply_markup=get_draft_edit_list_keyboard(draft, is_vip=vip_flag),
                )
            return

    was_editing_voice = chat_id in AWAITING_VOICE_EDIT
    if not was_editing_voice and (
        chat_id in AWAITING_QUESTION_MODE or is_question_or_catalog_inquiry(user_text)
    ):
        AWAITING_QUESTION_MODE.discard(chat_id)
        order_mode = get_user_order_mode(chat_id)
        vip_flag = is_user_vip(user_id)
        wait_qa = await update.message.reply_text("🔍 در حال بررسی کاتالوگ جامع و اشتراکات لنت‌ها...")
        try:
            catalog = load_catalog_from_excel(EXCEL_FILE_PATH)
            answer = answer_catalog_question(user_text, catalog, order_mode=order_mode, is_vip=vip_flag)
            if len(answer) <= 4000:
                await wait_qa.edit_text(answer)
            else:
                await wait_qa.edit_text(answer[:4000])
                for i in range(4000, len(answer), 4000):
                    await update.message.reply_text(answer[i:i+4000])
        except Exception as e:
            logger.exception("Error answering catalog question")
            await wait_qa.edit_text(f"❌ خطا در دریافت پاسخ:\n`{e}`", parse_mode="Markdown")
        return

    AWAITING_VOICE_EDIT.discard(chat_id)
    PENDING_VOICE_TEXTS.pop(chat_id, None)

    order_mode = get_user_order_mode(chat_id)
    vip_flag = is_user_vip(user_id)
    mode_short = "سفارش خرد" if order_mode == "retail" else "سفارش عمده"
    cleaned_text = normalize_automotive_stt_text(user_text)
    wait_msg = await update.message.reply_text(
        f"⏳ در حال تشخیص لنت‌های سفارش ({mode_short})..."
    )
    try:
        catalog = load_catalog_from_excel(EXCEL_FILE_PATH)
        order_data = extract_order_from_text(cleaned_text, catalog, order_mode=order_mode)

        if not order_data["items"]:
            warn_txt = "\n".join(order_data.get("warnings", []))
            await wait_msg.edit_text(
                f"⚠️ هیچ کالای قیمت‌داری از پیام شما استخراج نشد.\n{warn_txt}"
            )
            return

        if was_editing_voice:
            order_data["extra_note"] = cleaned_text

        pre_cust = PRE_SELECTED_ORDER_CUSTOMER.pop(chat_id, None)
        if pre_cust and is_missing_customer_name(order_data.get("customer_title")):
            order_data["customer_title"] = pre_cust
            order_data["name_confirmed"] = True

        pre_cust = PRE_SELECTED_ORDER_CUSTOMER.pop(chat_id, None)
        if pre_cust and is_missing_customer_name(order_data.get("customer_title")):
            order_data["customer_title"] = pre_cust
            order_data["name_confirmed"] = True

        auto_notice = enforce_wholesale_minimum_rule(order_data, chat_id)
        summary_txt = format_draft_order_summary(order_data, is_vip=vip_flag)
        if auto_notice:
            summary_txt = f"{auto_notice}\n\n{summary_txt}"

        PENDING_DRAFT_ORDERS[chat_id] = order_data
        await wait_msg.edit_text(
            summary_txt,
            parse_mode="Markdown",
            reply_markup=get_draft_summary_keyboard(is_vip=vip_flag, order_data=order_data, user_id=user_id),
        )

    except Exception as e:
        logger.exception("Error processing text order")
        await wait_msg.edit_text(f"❌ خطا در پردازش سفارش:\n`{e}`", parse_mode="Markdown")


async def handle_voice_order(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.effective_chat.id
    voice = update.message.voice or update.message.audio
    caption = update.message.caption or ""

    wait_msg = await update.message.reply_text("🎙 در حال گوش دادن به ویس و تبدیل به متن...")
    try:
        tg_file = await context.bot.get_file(voice.file_id)

        ext = "ogg"
        if getattr(voice, "mime_type", None):
            if "mp3" in voice.mime_type or "mpeg" in voice.mime_type:
                ext = "mp3"
            elif "wav" in voice.mime_type:
                ext = "wav"
            elif "m4a" in voice.mime_type or "mp4" in voice.mime_type:
                ext = "m4a"

        with tempfile.TemporaryDirectory() as tmpdir:
            audio_path = os.path.join(tmpdir, f"order_voice.{ext}")
            await tg_file.download_to_drive(audio_path)
            transcribed = transcribe_audio_high_accuracy(audio_path, ext)

        if caption:
            transcribed = f"{transcribed}\n{normalize_automotive_stt_text(caption)}"

        PENDING_VOICE_TEXTS[chat_id] = transcribed
        AWAITING_VOICE_EDIT.discard(chat_id)
        current_mode = get_user_order_mode(chat_id)

        keyboard = InlineKeyboardMarkup(
            [
                [
                    InlineKeyboardButton(
                        "✅ بله، متن ویس درست است (تشخیص لنت‌ها)", callback_data="confirm_voice_order"
                    )
                ],
                [
                    InlineKeyboardButton(
                        "✏️ ویرایش متن ویس", callback_data="edit_voice_order"
                    ),
                    InlineKeyboardButton(
                        "🏠 بازگشت به منوی اصلی", callback_data="back_to_main_menu"
                    ),
                ],
            ]
        )

        confirm_msg = (
            "🎙 **متن تشخیص داده شده از ویس شما:**\n\n"
            f"`{transcribed}`\n\n"
            f"🏷 **نوع سفارش فعلی:** `{get_order_mode_label(current_mode)}`\n\n"
            "❓ **آیا این متن مورد تایید است؟**\n"
            "_(پس از تایید، لیست لنت‌های تشخیص داده شده نیز قبل از صدور پیش‌فاکتور به شما نمایش داده می‌شود تا بتوانید تعداد، شیم یا ۵/۶ میل بودن هر لنت را با دکمه تغییر دهید)_"
        )
        await wait_msg.edit_text(
            confirm_msg,
            parse_mode="Markdown",
            reply_markup=keyboard,
        )

    except Exception as e:
        logger.exception("Error processing voice order")
        await wait_msg.edit_text(f"❌ خطا در پردازش پیام صوتی:\n`{e}`", parse_mode="Markdown")


async def handle_photo_order(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat_id = update.effective_chat.id
    user_id = update.effective_user.id if update.effective_user else chat_id
    photo = update.message.photo[-1]
    caption = (update.message.caption or "").strip()

    if (user_id == ADMIN_TELEGRAM_ID or is_user_vip(user_id)) and (
        caption.lower().startswith(("/addwelcome", "/setwelcome", "addwelcome", "عکس خوش آمد", "خوش آمد", "خوش امد"))
    ):
        if caption.lower().startswith("/setwelcome"):
            RUNTIME_WELCOME_PHOTOS.clear()
        if photo.file_id not in RUNTIME_WELCOME_PHOTOS:
            RUNTIME_WELCOME_PHOTOS.append(photo.file_id)
        joined_ids = ",".join(RUNTIME_WELCOME_PHOTOS)
        await update.message.reply_text(
            f"✅ **این تصویر به عکس‌های خوش‌آمدگویی ربات اضافه شد!** (تعداد عکس‌های فعلی: `{to_fa_num(len(RUNTIME_WELCOME_PHOTOS))}` عکس)\n\n"
            "📌 از این لحظه هر کاربری `/start` بزند، این عکس‌ها به صورت آلبوم در ابتدای پیام خوش‌آمدگویی برایش ارسال می‌شود.\n"
            "🔹 برای افزودن عکس‌های بعدی، کافی است عکس بعدی را هم با کپشن `/addwelcome` بفرستید.\n"
            "🔹 برای پاک کردن همه عکس‌ها دستور `/clearwelcome` را بزنید.\n\n"
            "💡 **برای ثبت دائمی در Koyeb (که با ری‌استارت سرور هم پاک نشود):**\n"
            "متغیر محیطی `WELCOME_PHOTOS` را در Koyeb برابر مقدار زیر قرار دهید:\n"
            f"`{joined_ids}`",
            parse_mode="Markdown",
        )
        return

    active_oid = USER_ACTIVE_ORDER_ID.get(chat_id)
    if active_oid and active_oid in ACTIVE_PAYMENT_ORDERS:
        ord_rec = ACTIVE_PAYMENT_ORDERS[active_oid]
        if ord_rec.get("status") == "awaiting_receipt":
            await forward_receipt_to_admin(update, context, ord_rec)
            return

    order_mode = get_user_order_mode(chat_id)
    vip_flag = is_user_vip(user_id)
    mode_short = "سفارش خرد" if order_mode == "retail" else "سفارش عمده"
    wait_msg = await update.message.reply_text(
        f"🖼 در حال خواندن تصویر سفارش ({mode_short}) و تشخیص لنت‌ها..."
    )
    try:
        catalog = load_catalog_from_excel(EXCEL_FILE_PATH)
        tg_file = await context.bot.get_file(photo.file_id)
        img_byte_arr = await tg_file.download_as_bytearray()

        order_data = extract_order_from_image(
            bytes(img_byte_arr), "image/jpeg", caption, catalog, order_mode=order_mode
        )

        if not order_data["items"]:
            warn_txt = "\n".join(order_data.get("warnings", []))
            await wait_msg.edit_text(
                f"⚠️ هیچ کالای قیمت‌داری از تصویر ارسالی استخراج نشد.\n{warn_txt}"
            )
            return

        auto_notice = enforce_wholesale_minimum_rule(order_data, chat_id)
        summary_txt = format_draft_order_summary(order_data, is_vip=vip_flag)
        if auto_notice:
            summary_txt = f"{auto_notice}\n\n{summary_txt}"

        PENDING_DRAFT_ORDERS[chat_id] = order_data
        await wait_msg.edit_text(
            summary_txt,
            parse_mode="Markdown",
            reply_markup=get_draft_summary_keyboard(is_vip=vip_flag, order_data=order_data, user_id=user_id),
        )

    except Exception as e:
        logger.exception("Error processing photo order")
        await wait_msg.edit_text(f"❌ خطا در پردازش تصویر سفارش:\n`{e}`", parse_mode="Markdown")


async def handle_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    chat_id = query.message.chat_id
    user_id = update.effective_user.id if update.effective_user else chat_id
    vip_flag = is_user_vip(user_id)
    data = query.data or ""
    if not data.startswith(("cust_submit_proforma:", "adm_", "acc_", "pre_", "draft_pick_cust:", "item_del:", "item_shim:", "toggle_")):
        try:
            await query.answer()
        except Exception:
            pass


    # ۰.۱ هندلرهای انتخاب/ثبت مشتری قبل یا حین ثبت سفارش (فقط مخصوص مدیر اصلی ADMIN_TELEGRAM_ID)
    if data.startswith(("pre_cust_page:", "pre_pick_cust:", "pre_reg_new_cust:", "pre_clear_cust:", "draft_choose_customer:", "draft_pick_cust:")) or data == "draft_reg_new_cust":
        if user_id != ADMIN_TELEGRAM_ID:
            await query.answer("⛔ این قابلیت منحصراً در اختیار مدیر سیستم است.", show_alert=True)
            return

    if data.startswith("pre_cust_page:"):
        _, o_mode, p_str = data.split(":")
        await query.edit_message_reply_markup(reply_markup=build_pre_order_customer_picker_kb(o_mode, page=int(p_str)))
        return

    if data.startswith("pre_pick_cust:"):
        _, cid, o_mode = data.split(":")
        c_rec = REGISTERED_CUSTOMERS.get(str(cid))
        if not c_rec:
            await query.answer("⚠️ مشتری یافت نشد.", show_alert=True)
            return
        USER_ORDER_MODES[chat_id] = o_mode
        PRE_SELECTED_ORDER_CUSTOMER[chat_id] = c_rec["full_title"]
        await query.answer(f"✅ مشتری «{c_rec['full_title']}» انتخاب شد.")
        await query.edit_message_text(
            f"✅ **مشتری انتخاب‌شده:** `{c_rec['full_title']}`\n"
            f"🏷 **حالت سفارش:** `{get_order_mode_label(o_mode)}`\n\n"
            "✍️ حالا لطفاً لیست لنت‌های سفارش را به صورت **متن، ویس یا عکس** ارسال فرمایید:",
            parse_mode="Markdown",
        )
        return

    if data.startswith("pre_reg_new_cust:"):
        o_mode = data.split(":")[1]
        USER_ORDER_MODES[chat_id] = o_mode
        ADMIN_STATE[chat_id] = {"mode": "awaiting_new_customer_pre_order", "order_mode": o_mode}
        await query.edit_message_text(
            "➕ **ثبت مشتری جدید برای سفارش:**\n\n"
            "✍️ لطفاً **نام مشتری و نام مغازه (لوازم یدکی)** را با خط تیره در چت تایپ و ارسال کنید\n"
            "_(مثال: `رضایی - لوازم یدکی بهار` یا `مهندس کریمی - فروشگاه پارس`)_:",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 انصراف", callback_data="back_to_main_menu")]]),
        )
        return

    if data.startswith("pre_clear_cust:"):
        o_mode = data.split(":")[1]
        USER_ORDER_MODES[chat_id] = o_mode
        PRE_SELECTED_ORDER_CUSTOMER.pop(chat_id, None)
        await query.edit_message_text(
            f"✅ بخش **`{get_order_mode_label(o_mode)}`** انتخاب شد.\n\n"
            "✍️ لطفاً سفارش خود را (به همراه نام دلخواه مشتری یا بدون نام) به صورت **متن، ویس یا عکس** ارسال فرمایید:",
            parse_mode="Markdown",
        )
        return

    if data.startswith("draft_choose_customer:"):
        page_num = int(data.split(":")[1])
        draft = PENDING_DRAFT_ORDERS.get(chat_id)
        if not draft:
            await query.edit_message_text("⚠️ سفارش فعلی منقضی شده است.")
            return
        USER_EDIT_STATE[chat_id] = {"mode": "awaiting_customer_name"}
        prompt_txt, kb_name = build_ask_customer_name_prompt_and_kb(update.effective_user, page=page_num)
        await query.edit_message_text(prompt_txt, parse_mode="Markdown", reply_markup=kb_name)
        return

    if data.startswith("draft_pick_cust:"):
        cid = data.split(":")[1]
        c_rec = REGISTERED_CUSTOMERS.get(str(cid))
        draft = PENDING_DRAFT_ORDERS.get(chat_id)
        if not draft or not c_rec:
            await query.answer("⚠️ اطلاعات سفارش یا مشتری یافت نشد.", show_alert=True)
            return
        USER_EDIT_STATE.pop(chat_id, None)
        draft["customer_title"] = c_rec["full_title"]
        draft["name_confirmed"] = True
        await query.answer(f"✅ مشتری «{c_rec['full_title']}» انتخاب شد.")
        await query.edit_message_text(
            format_draft_order_summary(draft, is_vip=vip_flag),
            parse_mode="Markdown",
            reply_markup=get_draft_summary_keyboard(is_vip=vip_flag, order_data=draft, user_id=user_id),
        )
        return

    if data == "draft_reg_new_cust":
        draft = PENDING_DRAFT_ORDERS.get(chat_id)
        if not draft:
            await query.edit_message_text("⚠️ سفارش فعلی یافت نشد.")
            return
        USER_EDIT_STATE.pop(chat_id, None)
        ADMIN_STATE[chat_id] = {"mode": "awaiting_new_customer_for_draft"}
        await query.edit_message_text(
            "➕ **ثبت مشتری جدید (نام و نام مغازه):**\n\n"
            "✍️ لطفاً **نام مشتری و نام مغازه** را با خط تیره تایپ و ارسال کنید\n"
            "_(مثال: `رضایی - لوازم یدکی بهار` یا `حسینی - فروشگاه مدرن`)_:",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 بازگشت به پیش‌نمایش سفارش", callback_data="draft_edit_menu")]]),
        )
        return

    # ۰.۲ هندلرهای بخش حسابداری انحصاری مدیر (acc_*)
    if data == "acc_dashboard" or data.startswith("acc_"):
        if user_id != ADMIN_TELEGRAM_ID:
            await query.answer("⛔ بخش حسابداری فقط مخصوص مدیر سیستم است.", show_alert=True)
            return

        if data == "acc_dashboard":
            ADMIN_STATE.pop(chat_id, None)
            try:
                await query.answer()
            except Exception:
                pass
            txt, kb = build_accounting_dashboard_text_and_kb()
            if query.message.document or query.message.photo:
                await query.message.reply_text(txt, parse_mode="Markdown", reply_markup=kb)
            else:
                await query.edit_message_text(txt, parse_mode="Markdown", reply_markup=kb)
            return

        if data == "acc_backup_db":
            save_accounting_db()
            await query.answer("💾 در حال ارسال فایل پشتیبان اطلاعات حسابداری...")
            if os.path.exists(ACCOUNTING_DB_PATH):
                with open(ACCOUNTING_DB_PATH, "rb") as bf:
                    await context.bot.send_document(
                        chat_id=chat_id,
                        document=bf,
                        filename=f"kialent_accounting_backup_{to_en_str(get_today_jalali()).replace('/', '-')}.json",
                        caption=(
                            "💾 **فایل پشتیبان کامل اطلاعات حسابداری، سفارش‌ها، پرداخت‌ها و مشتریان**\n\n"
                            "📌 هر زمان سرور را آپدیت یا جابه‌جا کردید، کافی است همین فایل `.json` را در چت برای ربات بفرستید تا تمام اطلاعات، سفارش‌ها، پرداخت‌ها و مشتریان بدون کم و کاست بازیابی شوند."
                        ),
                        parse_mode="Markdown",
                    )
            else:
                await query.message.reply_text("⚠️ هنوز فایلی برای پشتیبان‌گیری ثبت نشده است.")
            return

        if data == "acc_sync_gsheet":
            await query.answer("⏳ در حال ارتباط با گوگل‌شیت کارخانه...")
            ok, msg = sync_catalog_from_factory_gsheet()
            txt, kb = build_accounting_dashboard_text_and_kb()
            prefix = f"✅ {msg}" if ok else f"⚠️ {msg}"
            if query.message.document or query.message.photo:
                await query.message.reply_text(f"{prefix}\n\n{txt}", parse_mode="Markdown", reply_markup=kb)
            else:
                await query.edit_message_text(f"{prefix}\n\n{txt}", parse_mode="Markdown", reply_markup=kb)
            return

        if data.startswith("acc_menu_customers:"):
            ADMIN_STATE.pop(chat_id, None)
            try:
                await query.answer()
            except Exception:
                pass
            page = int(data.split(":")[1])
            txt, kb = build_customers_menu_text_and_kb(page=page)
            if query.message.document or query.message.photo:
                await query.message.reply_text(txt, parse_mode="Markdown", reply_markup=kb)
            else:
                await query.edit_message_text(txt, parse_mode="Markdown", reply_markup=kb)
            return

        if data == "acc_add_cust":
            ADMIN_STATE[chat_id] = {"mode": "awaiting_new_customer_reg"}
            await query.answer()
            msg_add_c = (
                "➕ **ثبت مشتری جدید در دفترچه مشتریان:**\n\n"
                "✍️ لطفاً **نام و نام خانوادگی مشتری** و **نام مغازه / لوازم یدکی** او را با خط تیره تایپ و ارسال کنید:\n"
                "• مثال ۱: `رضایی - لوازم یدکی بهار`\n"
                "• مثال ۲: `مهندس محمدی - فروشگاه پارس`\n"
                "• مثال ۳ (بدون نام مغازه): `جناب آقای حسینی`"
            )
            kb_cancel = InlineKeyboardMarkup([[InlineKeyboardButton("🔙 انصراف و بازگشت به مشتریان", callback_data="acc_menu_customers:0")]])
            if query.message.document or query.message.photo:
                await query.message.reply_text(msg_add_c, parse_mode="Markdown", reply_markup=kb_cancel)
            else:
                await query.edit_message_text(msg_add_c, parse_mode="Markdown", reply_markup=kb_cancel)
            return

        if data.startswith("acc_view_cust:"):
            cid = data.split(":")[1]
            await query.answer()
            txt, kb = build_single_customer_detail_text_and_kb(cid)
            if query.message.document or query.message.photo:
                await query.message.reply_text(txt, parse_mode="Markdown", reply_markup=kb)
            else:
                await query.edit_message_text(txt, parse_mode="Markdown", reply_markup=kb)
            return

        if data.startswith("acc_del_cust:"):
            cid = data.split(":")[1]
            removed_c = REGISTERED_CUSTOMERS.pop(str(cid), None)
            save_accounting_db()
            c_name = removed_c["full_title"] if removed_c else ""
            await query.answer(f"🗑 مشتری «{c_name}» از دفترچه حذف شد.", show_alert=True)
            txt, kb = build_customers_menu_text_and_kb(page=0)
            await query.edit_message_text(txt, parse_mode="Markdown", reply_markup=kb)
            return

        if data.startswith("acc_menu_open:"):
            ADMIN_STATE.pop(chat_id, None)
            try:
                await query.answer()
            except Exception:
                pass
            page = int(data.split(":")[1])
            txt, kb = build_open_orders_list_text_and_kb(page=page)
            if query.message.document or query.message.photo:
                await query.message.reply_text(txt, parse_mode="Markdown", reply_markup=kb)
            else:
                await query.edit_message_text(txt, parse_mode="Markdown", reply_markup=kb)
            return

        if data.startswith("acc_view_open:"):
            ADMIN_STATE.pop(chat_id, None)
            try:
                await query.answer()
            except Exception:
                pass
            oid = data.split(":")[1]
            txt, kb = build_single_open_order_text_and_kb(oid)
            if query.message.document or query.message.photo:
                await query.message.reply_text(txt, parse_mode="Markdown", reply_markup=kb)
            else:
                await query.edit_message_text(txt, parse_mode="Markdown", reply_markup=kb)
            return

        if data.startswith("acc_switch_mode:"):
            _, oid, target_mode = data.split(":")
            rec = ACCOUNTING_ORDERS.get(str(oid))
            if not rec:
                await query.answer("⚠️ سفارش یافت نشد.", show_alert=True)
                return
            od = rec["order_data"]
            od["order_mode"] = target_mode
            od["force_wholesale"] = (target_mode == "wholesale")
            od["admin_modified_pricing"] = True
            apply_order_mode_pricing_to_items(od["items"], order_mode=target_mode)
            save_accounting_db()
            mode_fa = "سفارش عمده" if target_mode == "wholesale" else "سفارش خرد"
            await query.answer(f"✅ قیمت سفارش #{to_fa_num(oid)} به «{mode_fa}» تغییر یافت.")
            txt, kb = build_single_open_order_text_and_kb(oid)
            if query.message.document or query.message.photo:
                await query.message.reply_text(txt, parse_mode="Markdown", reply_markup=kb)
            else:
                await query.edit_message_text(txt, parse_mode="Markdown", reply_markup=kb)
            return

        if data.startswith("acc_edit_open:"):
            import copy
            oid = data.split(":")[1]
            rec = ACCOUNTING_ORDERS.get(str(oid))
            if not rec:
                await query.answer("⚠️ سفارش یافت نشد.", show_alert=True)
                return
            await query.answer("✏️ ورود به منوی اصلاح اقلام سفارش باز")
            draft = copy.deepcopy(rec["order_data"])
            draft["editing_accounting_oid"] = str(oid)
            draft["name_confirmed"] = True
            PENDING_DRAFT_ORDERS[chat_id] = draft
            summary_txt = (
                f"✏️ **اصلاح سفارش باز `#{to_fa_num(oid)}`:**\n\n"
                + format_draft_order_summary(draft, is_vip=True)
                + "\n\n👇 روی هر لنت کلیک کنید تا تعداد، شیم یا ضخامت آن را تغییر دهید و در پایان **«✅ تایید نهایی»** را بزنید:"
            )
            kb_edit = get_draft_edit_list_keyboard(draft, is_vip=True)
            if query.message.document or query.message.photo:
                await query.message.reply_text(summary_txt, parse_mode="Markdown", reply_markup=kb_edit)
            else:
                await query.edit_message_text(summary_txt, parse_mode="Markdown", reply_markup=kb_edit)
            return

        if data.startswith("acc_to_invoice:"):
            oid = data.split(":")[1]
            rec = ACCOUNTING_ORDERS.get(str(oid))
            if not rec:
                await query.answer("⚠️ سفارش یافت نشد.", show_alert=True)
                return
            od = rec["order_data"]
            od["doc_type"] = "فاکتور"
            save_accounting_db()
            await query.answer("✅ به «فاکتور» تبدیل شد. در حال ارسال PDF...")
            pdf_bytes = generate_pdf_bytes(od)
            cust = od.get("customer_title", "مشتری")
            fin = calculate_order_financials(od["items"], order_data=od, ord_rec=rec)
            kb_inv = InlineKeyboardMarkup(
                [
                    [
                        InlineKeyboardButton(
                            "✅ پرداخت گردید (ثبت مبلغ پرداختی مشتری)",
                            callback_data=f"acc_mark_paid:{oid}",
                        )
                    ],
                    [
                        InlineKeyboardButton(
                            f"📂 بازگشت به مدیریت سفارش #{to_fa_num(oid)}",
                            callback_data=f"acc_view_open:{oid}",
                        )
                    ],
                ]
            )
            await context.bot.send_document(
                chat_id=chat_id,
                document=io.BytesIO(pdf_bytes),
                filename=f"فاکتور سفارش {cust} - کد {oid}.pdf",
                caption=(
                    f"🧾 **فاکتور رسمی سفارش `#{to_fa_num(oid)}` ({cust})**\n"
                    f"💰 مبلغ فاکتور: `{to_fa_num(fin['total_payable'], comma=True)} ریال`\n"
                    f"💳 سهم کارخانه (با ۲۰٪ تخفیف): `{to_fa_num(fin['factory_payable_total'], comma=True)} ریال`\n"
                    f"💎 سود خالص شما: `{to_fa_num(fin['net_profit'], comma=True)} ریال`"
                ),
                parse_mode="Markdown",
                reply_markup=kb_inv,
            )
            return

        if data.startswith("acc_dl_pdf:"):
            oid = data.split(":")[1]
            rec = ACCOUNTING_ORDERS.get(str(oid))
            if not rec:
                await query.answer("⚠️ سفارش یافت نشد.", show_alert=True)
                return
            od = rec["order_data"]
            doc_t = od.get("doc_type", "پیش‌فاکتور")
            cust = od.get("customer_title", "مشتری")
            await query.answer(f"📥 در حال ارسال فایل {doc_t}...")
            pdf_bytes = generate_pdf_bytes(od)
            fin = calculate_order_financials(od["items"], order_data=od, ord_rec=rec)
            await context.bot.send_document(
                chat_id=chat_id,
                document=io.BytesIO(pdf_bytes),
                filename=f"{doc_t} سفارش {cust} - کد {oid}.pdf",
                caption=(
                    f"📄 **{doc_t} سفارش `#{to_fa_num(oid)}` ({cust})**\n"
                    f"🧾 مبلغ فاکتور: `{to_fa_num(fin['total_payable'], comma=True)} ریال`\n"
                    f"💵 پرداختی مشتری: `{to_fa_num(fin['actual_paid_amount'], comma=True)} ریال`\n"
                    f"💳 سهم کارخانه (۲۰٪-): `{to_fa_num(fin['factory_payable_total'], comma=True)} ریال`\n"
                    f"💎 سود خالص شما: `{to_fa_num(fin['net_profit'], comma=True)} ریال`"
                ),
                parse_mode="Markdown",
            )
            return

        if data.startswith("acc_mark_paid:") or data.startswith("acc_edit_paid_amt:"):
            oid = data.split(":")[1]
